/**
 * The message list columns. Stormbox lets the user add columns, each
 * showing its own folder, and persists their folders and widths per
 * account; this build has the primary column only, whose folder is the
 * mail store's `currentFolderId`, and its width lasts for the page's
 * lifetime.
 */

import { defineStore } from 'pinia';
import { computed, ref } from 'vue';

import { useMailStore } from './mail-store';

export const MESSAGE_COLUMN_MIN_WIDTH = 280;
export const MESSAGE_COLUMN_MAX_WIDTH = 1920;
export const MESSAGE_COLUMN_DEFAULT_WIDTH = 360;
export const MESSAGE_COLUMN_RESIZER_WIDTH = 6;
export const PRIMARY_COLUMN_ID = 'primary';

/** A column as the columns area renders it. */
export interface MessageColumn {
  id: string;
  primary: boolean;
  folderId: number | null;
  width: number;
}

export function clampColumnWidth(width: number): number {
  const numeric = Number(width);
  if (!Number.isFinite(numeric)) return MESSAGE_COLUMN_DEFAULT_WIDTH;
  return Math.round(Math.max(
    MESSAGE_COLUMN_MIN_WIDTH,
    Math.min(MESSAGE_COLUMN_MAX_WIDTH, numeric),
  ));
}

export const useMessageColumnsStore = defineStore('messageColumns', () => {
  const mailStore = useMailStore();
  const primaryWidth = ref(MESSAGE_COLUMN_DEFAULT_WIDTH);
  /** The column a message was last opened from (the single-column layout scrolls back to it). */
  const lastActiveColumnId = ref<string | null>(null);

  const columns = computed<MessageColumn[]>(() => [{
    id: PRIMARY_COLUMN_ID,
    primary: true,
    folderId: mailStore.currentFolderId,
    width: primaryWidth.value,
  }]);

  function setColumnWidth(_id: string, width: number): void {
    primaryWidth.value = clampColumnWidth(width);
  }

  return {
    columns, lastActiveColumnId, setColumnWidth,
  };
});
