<script setup lang="ts">
/**
 * One positioned message-list row. Owns the row's markup and styling so
 * every list surface renders the same row;
 * selection, focus and drag state come in as props and every interaction
 * is emitted back to the owner.
 */
import { computed } from 'vue';
import {
  Paperclip, Star, Trash2,
} from '@lucide/vue';

import archiveIcon from '../assets/icons/tb-folder-archive.svg?raw';
import type { JmapViewSort } from '../constants/states';
import { useSenderAvatars } from '../composables/useSenderAvatars';
import {
  correspondentLabel,
  fmtDate,
  rowCorrespondent,
  rowTimestamp,
  type MessageRowLike,
} from '../utils/message-row-presentation';
import { resolveMessageTags, type MessageTagDefinition } from '../utils/message-tags';
import { isScheduledMessage } from '../utils/scheduled-message';
import MessageTagStack from './MessageTagStack.vue';

const props = withDefaults(defineProps<{
  message: MessageRowLike & { id: number };
  index: number;
  start: number;
  size: number;
  focused?: boolean;
  cursor?: boolean;
  selected?: boolean;
  dragging?: boolean;
  showsRecipients?: boolean;
  sort?: JmapViewSort;
  /** False on surfaces without multi-select: no checkbox is rendered. */
  selectable?: boolean;
  /**
   * Prefix of the row's DOM id (`${domIdPrefix}${message.id}`). Lists
   * that can show one folder side by side pass a per-list prefix so
   * `aria-activedescendant` and row anchors stay unique in the page.
   */
  domIdPrefix?: string;
  /**
   * Overlay tag / star / archive / delete at the row's inline-end on
   * hover. The star keeps its slot when the row is not hovered so a
   * starred message shows its star in the same place; the summary
   * reserves a slot for tag and star and the date sits under archive and
   * delete. The grid manages keyboard focus for these buttons. The
   * single-column layout has no hover menu; it always shows the star
   * (set or not) and never tag, archive or delete.
   */
  hoverActions?: boolean;
  /** False where archiving is a no-op (the Archive folder): the overlay drops its Archive button. */
  archiveAction?: boolean;
  /** False in a tag view, whose rows live in many folders: the overlay drops Delete. */
  deleteAction?: boolean;
  /** False where rows cannot be dragged to a folder (a tag view). */
  draggable?: boolean;
  /** True while this row's tag menu is open, for the Tag button's aria-expanded. */
  tagMenuOpen?: boolean;
  /**
   * Tag definitions that color the row's tag stack (MK-6.5). A keyword
   * without one draws as a neutral icon; names go in the stack's title.
   */
  tagDefinitions?: ReadonlyArray<MessageTagDefinition>;
}>(), {
  focused: false,
  cursor: false,
  selected: false,
  dragging: false,
  showsRecipients: false,
  sort: 'received',
  selectable: true,
  hoverActions: false,
  archiveAction: true,
  deleteAction: true,
  draggable: true,
  tagMenuOpen: false,
  domIdPrefix: 'msg-row-',
  tagDefinitions: () => [],
});

const emit = defineEmits<{
  (e: 'row-click', event: MouseEvent): void;
  (e: 'checkbox-click', event: MouseEvent): void;
  (e: 'dragstart', event: DragEvent): void;
  (e: 'dragend', event: DragEvent): void;
  (e: 'star'): void;
  /** Open the tag menu for this row, anchored to the button that raised it. */
  (e: 'tag', event: MouseEvent): void;
  /** A chip was clicked: the owner filters the list to that tag. */
  (e: 'archive'): void;
  (e: 'delete'): void;
}>();

const { senderAvatar, onAvatarError } = useSenderAvatars();

const isUnread = computed(() => Number(props.message.is_seen) === 0);
const isFlagged = computed(() => Number(props.message.is_flagged) === 1);
const tags = computed(() => resolveMessageTags(props.message.keywords_json, props.tagDefinitions));
const tagStackLabel = computed(() => (
  tags.value.length === 0 ? 'Tag' : `Tags: ${tags.value.map((tag) => tag.name).join(', ')}`
));
const correspondent = computed(() => rowCorrespondent(props.message, props.showsRecipients));
const avatar = computed(() => senderAvatar(correspondent.value));
const label = computed(() => correspondentLabel(props.message, props.showsRecipients));
const dateText = computed(() => fmtDate(rowTimestamp(props.message, props.sort)));
const rowLabel = computed(() => [
  label.value,
  props.message.subject || '(no subject)',
  dateText.value,
  isUnread.value ? 'Unread' : '',
  isFlagged.value ? 'Starred' : '',
  Number(props.message.has_attachment) === 1 ? 'Has attachments' : '',
  tags.value.length > 0 ? tagStackLabel.value : '',
].filter(Boolean).join(', '));
</script>

<template>
  <li
    :id="`${domIdPrefix}${message.id}`"
    :data-index="index"
    role="row"
    :aria-rowindex="index + 1"
    :aria-label="rowLabel"
    :aria-selected="selected"
    :class="{
      'is-focused': focused,
      'is-cursor': cursor,
      'is-selected': selected,
      'is-dragging': dragging,
      'is-unread': isUnread,
      'is-unselectable': !selectable,
    }"
    :style="{
      position: 'absolute',
      top: '0px',
      left: '0px',
      right: '0px',
      transform: `translateY(${start}px)`,
      height: size + 'px',
    }"
  >
    <div
      class="msg-list__item"
      :class="{ 'msg-list__item--hover-actions': hoverActions, 'has-tag-menu': tagMenuOpen }"
      role="gridcell"
      :draggable="draggable && !isScheduledMessage(message)"
      @click="emit('row-click', $event)"
      @dragstart="emit('dragstart', $event)"
      @dragend="emit('dragend', $event)"
    >
      <button
        type="button"
        class="msg-list__open"
        data-message-control
        tabindex="-1"
        :aria-label="`Open message: ${message.subject || '(no subject)'}, ${label}`"
      />
      <div class="msg-list__state">
        <label v-if="selectable" class="msg-list__check" draggable="false" @click.stop>
          <input
            type="checkbox"
            data-message-control
            tabindex="-1"
            :aria-label="`Select message: ${message.subject || '(no subject)'}, ${label}`"
            :checked="selected"
            @click="emit('checkbox-click', $event)"
          />
        </label>
        <span
          v-if="isUnread"
          class="msg-list__unread-dot"
          aria-hidden="true"
        />
      </div>
      <div
        class="msg-list__avatar"
        :style="avatar.style"
        aria-hidden="true"
      >
        <img
          v-if="avatar.imageUrl"
          class="msg-list__avatar-image"
          :src="avatar.imageUrl"
          alt=""
          loading="lazy"
          decoding="async"
          referrerpolicy="no-referrer"
          @error="onAvatarError(correspondent)"
        />
        <span>{{ avatar.initials }}</span>
      </div>
      <div class="msg-list__content">
        <div class="msg-list__summary">
          <span class="msg-list__from">{{ label }}</span>
          <span class="msg-list__subject">{{ message.subject || '(no subject)' }}</span>
          <span class="msg-list__icons">
            <Star v-if="isFlagged && !hoverActions" :size="13" :stroke-width="2" class="msg-list__star" />
            <Paperclip v-if="Number(message.has_attachment) === 1" :size="13" :stroke-width="1.75" class="msg-list__attach" />
            <MessageTagStack
              v-if="!hoverActions && tags.length > 0"
              :tags="tags"
              :title="tagStackLabel"
              data-row-tags
            />
          </span>
          <span class="msg-list__date">{{ dateText }}</span>
          <div
            v-if="hoverActions"
            class="msg-list__actions"
            draggable="false"
            @click.stop
          >
            <!-- The row's tag control (MK-6.5): the tag stack, shown at
                 rest while the row carries tags and on hover otherwise;
                 clicking opens the tag menu. -->
            <button
              type="button"
              class="msg-list__action msg-list__action--tag"
              :class="{ 'is-tagged': tags.length > 0 }"
              tabindex="-1"
              data-message-control
              :title="tagStackLabel"
              :aria-label="tagStackLabel"
              aria-haspopup="dialog"
              :aria-expanded="tagMenuOpen"
              data-row-tags
              @click="emit('tag', $event)"
            >
              <MessageTagStack :tags="tags" />
            </button>
            <button
              type="button"
              class="msg-list__action msg-list__action--star"
              :class="{ 'msg-list__action--starred': isFlagged }"
              tabindex="-1"
              data-message-control
              :title="isFlagged ? 'Unstar' : 'Star'"
              :aria-label="isFlagged ? 'Unstar' : 'Star'"
              :aria-pressed="isFlagged"
              @click="emit('star')"
            >
              <Star :size="17" :stroke-width="1.75" :fill="isFlagged ? '#facc15' : 'none'" />
            </button>
            <button
              v-if="archiveAction"
              type="button"
              class="msg-list__action"
              tabindex="-1"
              data-message-control
              title="Archive"
              aria-label="Archive"
              @click="emit('archive')"
            >
              <span class="msg-list__action-icon--folder" aria-hidden="true" v-html="archiveIcon" />
            </button>
            <button
              v-if="deleteAction"
              type="button"
              class="msg-list__action msg-list__action--danger"
              tabindex="-1"
              data-message-control
              title="Delete"
              aria-label="Delete"
              @click="emit('delete')"
            >
              <Trash2 :size="18" :stroke-width="1.65" />
            </button>
          </div>
        </div>
        <p v-if="message.preview" class="msg-list__preview">
          {{ message.preview }}
        </p>
      </div>
    </div>
  </li>
</template>

<style scoped>
/* Fastmail model: the focused row (currently being viewed) gets the
 * solid accent background. Selection state is communicated by the
 * checkbox itself; we tint the row very softly so the user can scan
 * a column of selected rows without it competing with the "what
 * am I reading" highlight. */
.msg-list__items li.is-focused .msg-list__item { background: var(--rowActive); }
.msg-list__items li.is-selected .msg-list__item {
  background: color-mix(in srgb, var(--accent) 6%, var(--panel));
}
.msg-list__items li.is-selected.is-focused .msg-list__item {
  background: var(--rowActive);
}
.msg-list__items li.is-dragging .msg-list__item {
  opacity: 0.55;
}
.msg-list__items li.is-unread .msg-list__from,
.msg-list__items li.is-unread .msg-list__subject {
  font-weight: 600;
  color: var(--text);
}

.msg-list__item {
  position: relative;
  display: grid;
  grid-template-columns: 34px 34px minmax(0, 1fr);
  align-items: center;
  column-gap: 10px;
  width: 100%;
  height: 100%;
  text-align: left;
  padding: 7px 14px 7px 12px;
  border: 0;
  background: transparent;
  cursor: pointer;
  border-bottom: 1px solid var(--border-soft);
  font: inherit;
  color: inherit;
  transition: background 0.06s ease;
  /* Stops Shift-click from accidentally selecting subject text as
   * the user extends a range — the native text-selection range
   * appears on top of the row highlight and is very ugly. */
  user-select: none;
  -webkit-user-select: none;
}
.msg-list__item:hover,
.msg-list__item:focus-within,
.msg-list__item.has-tag-menu { background: var(--rowHover); }
.msg-list__scroller:focus-visible .is-cursor .msg-list__item {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.msg-list__open {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  cursor: pointer;
}
.msg-list__state,
.msg-list__avatar,
.msg-list__content {
  pointer-events: none;
}
.msg-list__check,
.msg-list__content [data-row-tags] {
  pointer-events: auto;
}
.msg-list__content {
  min-width: 0;
}
.msg-list__open:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.msg-list__action:focus-visible,
.msg-list__check input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.msg-list__item.has-tag-menu .msg-list__action--tag,
.msg-list__item:focus-within .msg-list__action--tag {
  visibility: visible;
}
.msg-list__item:focus-within .msg-list__check {
  opacity: 1;
}
.msg-list__item:focus-within .msg-list__unread-dot {
  opacity: 0;
}

/* The action overlay is centred on the summary line, over its last three
   columns: star over its 34px slot, archive and delete over the 64px date
   (34 + 8 + 64 = 106 ≥ 3 × 34 + 2 × 2), and the tag stack first, 2px
   before the star like every other action. The overlay is anchored at its
   end, so a wider stack grows leftward into the reserved 56px slot and the
   8px gap after it. The preview line below stays uncovered. At rest only a set star and a tagged row's
   stack are visible; hovering the row shows all four on the row's own
   background. The single-column layout (App.vue SINGLE_COLUMN_WIDTH) has
   no hover: the star and a tagged stack are always visible in their slots
   and archive and delete are not rendered. */
.msg-list__actions {
  position: absolute;
  inset-inline-end: 0;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  gap: 2px;
  pointer-events: none;
}
.msg-list__action {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font: inherit;
  flex-shrink: 0;
  visibility: hidden;
  pointer-events: auto;
}
.msg-list__action--starred,
.msg-list__action--tag.is-tagged {
  visibility: visible;
}
/* Sized to its stack; 55px at most for three icons and "+N". */
.msg-list__action--tag {
  width: auto;
  min-width: 34px;
  padding: 0 6px;
}
@media (min-width: 640px) {
  /* Inherit down the chain so the overlay matches hover, focused and
     selected row fills alike. */
  .msg-list__item--hover-actions.has-tag-menu .msg-list__content,
  .msg-list__item--hover-actions.has-tag-menu .msg-list__summary,
  .msg-list__item--hover-actions.has-tag-menu .msg-list__actions,
  .msg-list__item--hover-actions:focus-within .msg-list__content,
  .msg-list__item--hover-actions:focus-within .msg-list__summary,
  .msg-list__item--hover-actions:focus-within .msg-list__actions,
  .msg-list__item--hover-actions:hover .msg-list__content,
  .msg-list__item--hover-actions:hover .msg-list__summary,
  .msg-list__item--hover-actions:hover .msg-list__actions {
    background: inherit;
  }
  .msg-list__item--hover-actions:focus-within .msg-list__action,
  .msg-list__item--hover-actions:hover .msg-list__action {
    visibility: visible;
  }
}
@media (max-width: 639px) {
  .msg-list__actions {
    /* Sit on the star slot only: the date column and the gap before it. */
    inset-inline-end: 72px;
  }
  .msg-list__action--star {
    visibility: visible;
  }
  .msg-list__action:not(.msg-list__action--star, .msg-list__action--tag) {
    display: none;
  }
}
.msg-list__action:hover:where(:not(:disabled)) {
  background: var(--control-hover-bg);
  color: var(--text);
}
.msg-list__action--starred,
.msg-list__action--starred:hover {
  color: var(--folder-icon-color);
}
.msg-list__action--danger:hover:where(:not(:disabled)) {
  background: var(--error-bg);
  color: var(--error-fg);
}
.msg-list__action-icon--folder {
  display: block;
  width: 20px;
  height: 20px;
}
.msg-list__action-icon--folder :deep(svg) {
  display: block;
  width: 100%;
  height: 100%;
}
.msg-list__action-icon--folder :deep([fill="context-fill"]) {
  fill: color-mix(in srgb, currentColor 20%, transparent);
}
.msg-list__action-icon--folder :deep([fill="context-stroke"]) {
  fill: currentColor;
}

.msg-list__state {
  position: relative;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
}
.msg-list__check {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 6px;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.08s ease;
}
.msg-list__check input {
  width: 14px;
  height: 14px;
  margin: 0;
  cursor: pointer;
  accent-color: var(--accent);
}

.msg-list__unread-dot {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  transition: opacity 0.08s ease;
  /* Pure visual indicator: never intercept clicks meant for the
   * underlying checkbox (which has inset: 0 within .msg-list__state). */
  pointer-events: none;
}
.msg-list__item:hover .msg-list__check,
.msg-list__items li.is-selected .msg-list__check {
  opacity: 1;
}
.msg-list__item:hover .msg-list__unread-dot,
.msg-list__items li.is-selected .msg-list__unread-dot {
  opacity: 0;
}
/* Without a checkbox there is nothing for the dot to make room for. */
.msg-list__items li.is-unselectable .msg-list__item:hover .msg-list__unread-dot {
  opacity: 1;
}
.msg-list__avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  overflow: hidden;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #fff 22%, transparent);
}
.msg-list__avatar-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.msg-list__summary {
  display: grid;
  grid-template-columns: clamp(86px, 28%, 200px) minmax(0, 1fr) auto auto;
  grid-template-areas: "from subject icons date";
  align-items: baseline;
  column-gap: 8px;
}
/* Reserve the tag stack and star overlay slots and pin the date to the
   width archive and delete cover (see .msg-list__actions). */
.msg-list__item--hover-actions .msg-list__summary {
  position: relative;
  grid-template-columns: clamp(86px, 28%, 200px) minmax(0, 1fr) auto 56px 34px 64px;
  grid-template-areas: "from subject icons tag star date";
}
.msg-list__item--hover-actions .msg-list__date {
  text-align: end;
}
.msg-list__from {
  grid-area: from;
  min-width: 0;
  font-size: 13px;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.msg-list__date {
  grid-area: date;
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.msg-list__subject {
  grid-area: subject;
  min-width: 0;
  font-size: 13px;
  color: var(--text);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.msg-list__icons {
  grid-area: icons;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  min-width: 0;
}

.msg-list__star {
  color: var(--folder-icon-color);
  fill: #facc15;
}
.msg-list__preview {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--muted);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  line-height: 1.35;
}

.msg-list--card .msg-list__item {
  grid-template-columns: 24px 34px minmax(0, 1fr);
  align-items: start;
  column-gap: 9px;
  padding: 10px 12px;
}
.msg-list--card .msg-list__state {
  width: 24px;
}
.msg-list--card .msg-list__summary {
  grid-template-columns: minmax(0, 1fr) auto auto;
  grid-template-areas:
    "from icons date"
    "subject subject subject";
  row-gap: 2px;
}
/* Stacked rows keep the tag stack and star slots on the sender line so
   the overlay never sits on the wrapped subject. */
.msg-list--card .msg-list__item--hover-actions .msg-list__summary {
  grid-template-columns: minmax(0, 1fr) auto 56px 34px 64px;
  grid-template-areas:
    "from icons tag star date"
    "subject subject subject subject subject";
}
.msg-list--card .msg-list__actions {
  top: 9px;
}
.msg-list--card .msg-list__action:focus-visible {
  outline: none;
}
.msg-list--card .msg-list__action:focus-visible::after {
  content: '';
  position: absolute;
  inset: 4px 0;
  border: 2px solid var(--accent);
  border-radius: 4px;
  pointer-events: none;
}
.msg-list--card .msg-list__from,
.msg-list--card .msg-list__subject {
  font-size: 13px;
}
.msg-list--card .msg-list__subject {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.3;
}
.msg-list--card .msg-list__preview {
  margin-top: 3px;
  -webkit-line-clamp: 1;
}

@media (max-width: 639px) {
  .msg-list__check {
    opacity: 1;
  }
  .msg-list__unread-dot {
    opacity: 0;
  }
}
</style>
