/**
 * User settings. Stormbox syncs these through JMAP and keeps a local
 * copy in SQLite; here they live in memory for the page's lifetime. The
 * theme starts dark unless the URL asks for `?theme=light`, so every run
 * starts from the same colors.
 */

import { defineStore } from 'pinia';
import { reactive } from 'vue';

import type { Palette, ShortcutScheme, Theme } from '../constants/settings';
import { TIME_ZONE } from '../clock';
import { DEFAULT_MESSAGE_TAGS, type MessageTagDefinition } from '../utils/message-tags';

export interface Settings {
  theme: Theme;
  palette: Palette;
  shortcutScheme: ShortcutScheme;
  timeZone: string;
  messageTags: MessageTagDefinition[];
}

function initialTheme(): Theme {
  if (typeof location === 'undefined') return 'dark';
  return new URLSearchParams(location.search).get('theme') === 'light' ? 'light' : 'dark';
}

export const useSettingsStore = defineStore('settings', () => {
  const values = reactive<Settings>({
    theme: initialTheme(),
    palette: 'classic',
    shortcutScheme: 'web',
    timeZone: TIME_ZONE,
    messageTags: [...DEFAULT_MESSAGE_TAGS],
  });

  function get<K extends keyof Settings>(key: K): Settings[K] {
    return values[key] as Settings[K];
  }

  async function update(patch: Partial<Settings>): Promise<void> {
    Object.assign(values, patch);
  }

  return { get, update };
});
