<script setup lang="ts">
import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
  useId,
  watch,
} from 'vue';
import DOMPurify from 'dompurify';
import { useElementSize, useMediaQuery } from '@vueuse/core';
import {
  ArrowLeft,
  ChevronDown,
  Clock,
  Moon,
  Sun,
  Trash2,
} from '@lucide/vue';

import { useMessageTags } from '../composables/useMessageTags';
import { requestTagManager } from '../composables/useTagManagerRequest';
import { invokeThunderbirdShortcut } from '../composables/useThunderbirdShortcuts';
import { useComposeStore } from '../stores/compose-store';
import { useMailStore } from '../stores/mail-store';
import { useSettingsStore } from '../stores/settings-store';
import { LOCALE, NOW, TIME_ZONE } from '../clock';
import {
  ALLOWED_URI_REGEXP,
  BODY_THEME_COLORS,
  BOLT_BODY_BACKGROUND,
  IFRAME_SANDBOX,
  buildMessageSrcDoc,
  sanitizeMessageDocument,
} from '../utils/message-html';
import { adaptHtmlForDarkMode } from '../utils/dark-email';
import { formatAddressList } from '../utils/address-parse';
import { titleWithShortcut, type ShortcutAction } from '../constants/shortcuts';
import { plaintextToHtml } from '../utils/plaintext-html';
import { shortFrom } from '../utils/sender-avatar';
import { isScheduledMessage } from '../utils/scheduled-message';
import archiveIcon from '../assets/icons/tb-folder-archive.svg?raw';
import junkIcon from '../assets/icons/tb-folder-spam.svg?raw';
import forwardIcon from '../assets/icons/tb-forward.svg?raw';
import replyIcon from '../assets/icons/tb-reply.svg?raw';
import replyAllIcon from '../assets/icons/tb-reply-all.svg?raw';
import AppIconButton from './AppIconButton.vue';
import MaximizeButton from './MaximizeButton.vue';
import MessageAttachmentBar, { type MessageAttachmentRow } from './MessageAttachmentBar.vue';
import MessageTagChip from './MessageTagChip.vue';
import MessageTagStack from './MessageTagStack.vue';
import TagPickerPopover, { type PopoverAnchor } from './TagPickerPopover.vue';

// Minimum logical width we lay HTML email out at before scaling down.
// Reflowing typical marketing HTML below this gets visually messy
// (image-heavy headers collapse, multi-column tables stack awkwardly,
// inline buttons overlap). Below this shell width we therefore treat
// content as if it has at least this width and apply CSS zoom to fit,
// even when scrollWidth would technically not overflow.
const MIN_EMAIL_LAYOUT_WIDTH = 400;

const props = withDefaults(defineProps<{ maximized?: boolean }>(), { maximized: false });
const emit = defineEmits<{ toggleMaximized: [] }>();
const messageViewEl = ref<HTMLElement | null>(null);
const { height: messageViewHeight } = useElementSize(messageViewEl, undefined, { box: 'border-box' });
const toolbarEl = ref<HTMLElement | null>(null);
const scheduledBannerEl = ref<HTMLElement | null>(null);
const attachmentBarEl = ref<HTMLElement | null>(null);
const { height: toolbarHeight } = useElementSize(toolbarEl, undefined, { box: 'border-box' });
const { height: scheduledBannerHeight } = useElementSize(scheduledBannerEl, undefined, { box: 'border-box' });
const { height: attachmentBarHeight } = useElementSize(attachmentBarEl, undefined, { box: 'border-box' });
const bodyScrollEl = ref<HTMLElement | null>(null);
watch(() => props.maximized, async (maximized) => {
  if (!maximized) return;
  await nextTick();
  if (!messageViewEl.value?.contains(document.activeElement)) {
    messageViewEl.value?.focus({ preventScroll: true });
  }
});

let sizeChange = 0;
let fitIframe: (() => void) | null = null;
async function toggleMaximized() {
  const messageId = mailStore.selectedMessageId;
  const bodyEl = bodyScrollEl.value;
  const scrollRange = bodyEl ? bodyEl.scrollHeight - bodyEl.clientHeight : 0;
  const progress = scrollRange > 0 && bodyEl ? bodyEl.scrollTop / scrollRange : 0;
  const frame = iframeRef.value as HTMLIFrameElement | null;
  const frameDoc = frame?.contentDocument;
  const bodyTop = bodyEl?.getBoundingClientRect().top ?? 0;
  const frameTop = frame?.getBoundingClientRect().top ?? 0;
  const bodyBottom = bodyEl?.getBoundingClientRect().bottom ?? 0;
  const anchor = [...(frameDoc?.body.querySelectorAll('*') ?? [])].find((element) => {
    if (element.childElementCount) return false;
    const rect = element.getBoundingClientRect();
    return rect.height > 0 && rect.bottom + frameTop > bodyTop && rect.top + frameTop < bodyBottom;
  });
  const anchorOffset = anchor ? frameTop + anchor.getBoundingClientRect().top - bodyTop : 0;
  const change = ++sizeChange;
  emit('toggleMaximized');
  await nextTick();
  fitIframe?.();
  await nextTick();
  window.requestAnimationFrame(() => window.requestAnimationFrame(() => {
    if (change === sizeChange && messageId === mailStore.selectedMessageId && bodyEl?.isConnected) {
      if (anchor?.isConnected && frame?.isConnected) {
        bodyEl.scrollTop += frame.getBoundingClientRect().top + anchor.getBoundingClientRect().top
          - bodyEl.getBoundingClientRect().top - anchorOffset;
      } else {
        bodyEl.scrollTop = progress * (bodyEl.scrollHeight - bodyEl.clientHeight);
      }
    }
  }));
}

const mailStore = useMailStore();
const composeStore = useComposeStore();
const settingsStore = useSettingsStore();
const shortcutScheme = computed(() => settingsStore.get('shortcutScheme'));
/** Toolbar title with the key the active scheme binds, e.g. `Reply (R)`. */
function actionTitle(label: string, action: ShortcutAction): string {
  return props.maximized ? label : titleWithShortcut(label, action, shortcutScheme.value);
}

function onReadingKeyDown(event: KeyboardEvent) {
  if (!props.maximized || event.key !== 'Escape' || event.defaultPrevented
    || composeStore.isExpanded || tagMenuAnchor.value
    || messageViewEl.value?.querySelector('[role="dialog"], details[open]')) return;
  event.preventDefault();
  void toggleMaximized();
}

const htmlShellRef = ref(null);
const iframeRef = ref(null);
const iframeSrcDoc = ref('');
const iframeHeight = ref(120);
const effectiveColorScheme = ref(getEffectiveColorScheme());
// Allow the user to disable dark mode in the message view only,
// independently of the global theme toggle. Resets when the open message
// changes so it's not a sticky preference.
const forceLightBody = ref(false);

// App theme, unless this one message has been escaped to light.
const bodyColorScheme = computed(() =>
  (effectiveColorScheme.value === 'dark' && forceLightBody.value)
    ? 'light'
    : effectiveColorScheme.value);
const iframeBackground = computed(() => {
  const scheme = bodyColorScheme.value === 'dark' ? 'dark' : 'light';
  return settingsStore.get('palette') === 'bolt'
    ? BOLT_BODY_BACKGROUND[scheme]
    : BODY_THEME_COLORS[scheme].background;
});

const body = computed(() => mailStore.messageBody);
// null while the body is still loading; a (possibly empty) object once the
// load completes. Used to show the loading placeholder only while loading,
// not for a message that has genuinely no body content.
const bodyLoaded = computed(() => body.value != null);

// Render plaintext bodies the way Thunderbird Desktop does: keep the
// original line breaks/whitespace (white-space: pre-wrap), linkify URLs
// and addresses, and tag quoted lines. The converter only emits escaped
// text plus our own anchor/span tags, but we still sanitize for defence
// in depth (and to keep target/rel on the generated links).
const textHtml = computed(() => {
  const raw = body.value?.text;
  if (!raw) return '';
  return DOMPurify.sanitize(plaintextToHtml(raw), {
    ALLOWED_URI_REGEXP,
    ADD_ATTR: ['target'],
  });
});
// The open message is resolved by the store from the folder it was
// opened in, so a message read from any list column shows here.
const message = computed(() => mailStore.openMessage ?? null);
const selectedMessageId = computed(() => mailStore.selectedMessageId);
const compactHeader = useMediaQuery('(max-width: 639px)');
const headerExpanded = ref(false);
const metadataExpanded = computed(() => !compactHeader.value || headerExpanded.value);
const metadataId = useId();
const metadataEl = ref<HTMLDListElement | null>(null);
watch(compactHeader, (compact) => {
  if (compact) return;
  const active = document.activeElement;
  if (active === metadataEl.value || active === messageViewEl.value?.querySelector('.message-view__details-toggle')) {
    bodyScrollEl.value?.focus({ preventScroll: true });
  }
});
const senderText = computed(() => metadataExpanded.value
  ? message.value?.from_text || '(no sender)'
  : shortFrom(message.value?.from_text));
const headerDetailsLabel = computed(() => headerExpanded.value ? 'Hide message details' : 'Show message details');
watch(selectedMessageId, () => {
  headerExpanded.value = false;
  if (metadataEl.value) metadataEl.value.scrollTop = 0;
});
function toggleHeaderDetails() {
  headerExpanded.value = !headerExpanded.value;
  if (metadataEl.value) metadataEl.value.scrollTop = 0;
}
/** Folder the open message was opened from; folder-specific actions act on it. */
const messageSource = computed(() => ({ sourceFolderId: mailStore.openMessageFolderId }));

// Tags on the open message (MK-6.5): the tag stack in the toolbar opens
// the tag menu, and the header lists the tags as removable chips. The
// single-column layout has no row hover, so this is where a phone user
// tags a single message.
const { definitions: tagDefinitions, tagsFor } = useMessageTags();
const messageTags = computed(() => tagsFor(message.value));
const messageTagTargets = computed(() => (message.value ? [message.value] : []));
const canTagMessage = computed(() => message.value != null && !isScheduledMessage(message.value));

// The toolbar's tag stack opens the menu as a popover: the header sits in
// an overflow-hidden article, which would clip an inline dropdown.
const tagMenuButton = ref<InstanceType<typeof AppIconButton> | null>(null);
const tagMenuTrigger = computed<HTMLElement | null>(() => (tagMenuButton.value?.$el as HTMLElement | undefined) ?? null);
const tagMenuAnchor = ref<PopoverAnchor | null>(null);
const tagStackLabel = computed(() => (
  messageTags.value.length === 0 ? 'Tag' : `Tags: ${messageTags.value.map((tag) => tag.name).join(', ')}`
));
function toggleTagMenu() {
  if (tagMenuAnchor.value) {
    tagMenuAnchor.value = null;
    return;
  }
  const rect = tagMenuTrigger.value?.getBoundingClientRect();
  if (!rect) return;
  tagMenuAnchor.value = {
    top: rect.top, left: rect.left, width: rect.width, height: rect.height,
  };
}
function closeTagMenu() {
  tagMenuAnchor.value = null;
}
// A different message (or none) closes the menu with the row it was for.
watch(() => message.value?.id, closeTagMenu);

async function setMessageTag(keyword: string, on: boolean) {
  if (!message.value) return;
  await mailStore.setTagsMany(
    [message.value.id],
    on ? { add: [keyword] } : { remove: [keyword] },
    messageSource.value,
  );
}

async function clearMessageTags() {
  if (!message.value) return;
  await mailStore.clearTagsMany([message.value.id], { ...messageSource.value, rows: [message.value] });
}

function manageTags() {
  closeTagMenu();
  requestTagManager();
}

// Stormbox downloads, previews and retries attachments through the
// repository; generated attachments have no bytes, so their rows offer
// Download only.
const attachmentRows = computed<MessageAttachmentRow[]>(() => (
  (body.value?.attachments ?? []).map((part, index) => ({
    key: `${selectedMessageId.value}:${index}`,
    part,
  }))
));
watch([attachmentRows, messageViewEl], () => {
  attachmentBarEl.value = messageViewEl.value?.querySelector<HTMLElement>('.message-attachment-bar') ?? null;
}, { flush: 'post' });

/**
 * The message's Cc and Bcc recipients, so the audience is visible before
 * replying (CS-2.7). There is no `cc_text` column, and there should not be:
 * the addresses are already cached one per row, which is the form Reply All
 * needs anyway. Bcc is only ever present on the user's own copy (drafts,
 * scheduled, Sent); the server strips the header before delivery (RFC 8621
 * §7.5), so a received message has none to show.
 */
function addressText(kind: 'cc' | 'bcc') {
  return formatAddressList(
    mailStore.selectedMessageAddresses
      .filter((row) => row.kind === kind && row.email)
      .sort((a, b) => a.position - b.position)
      .map((row) => ({ ...(row.name ? { name: row.name } : {}), email: row.email })),
  );
}
const ccText = computed(() => addressText('cc'));
const bccText = computed(() => addressText('bcc'));

let resizeObserver = null;
let iframeMeasurementCleanup = null;
let themeMediaQuery = null;
let themeMutationObserver = null;

function applyHtmlSrcDoc(html, colorScheme) {
  const nextSrcDoc = buildMessageSrcDoc(html, { colorScheme });
  // Only reset the height when the srcdoc actually changes. The
  // mail-store fires `refreshMessageBody` twice per `selectMessage`
  // call (once immediately, once after the body-prefetch queue
  // resolves) — both runs assign a fresh body object with the same
  // content. Vue's reactive setter sees a new object reference and
  // re-runs this watch, but the computed srcdoc string is identical.
  // Setting `srcdoc` to the same string is a no-op in the DOM (the
  // iframe doesn't reload, so `load` never refires), and an
  // unconditional `iframeHeight = 120` reset would clobber the height
  // measure() already set — leaving the iframe stuck at 120 px on
  // every fresh open.
  if (nextSrcDoc === iframeSrcDoc.value) return;
  teardownResizeObserver();
  iframeSrcDoc.value = nextSrcDoc;
  iframeHeight.value = 120;
  nextTick(() => {
    if (iframeSrcDoc.value === nextSrcDoc) {
      iframeHeight.value = Math.max(iframeHeight.value, 120);
    }
  });
}

// Stormbox first resolves the body's inline `cid:` images to data: URLs
// through the repository, which makes this render asynchronous; generated
// bodies reference none, so it runs synchronously here.
function renderHtmlBody(next, colorScheme) {
  if (!next?.html) {
    teardownResizeObserver();
    iframeSrcDoc.value = '';
    iframeHeight.value = 120;
    return;
  }
  // Adapt for dark before building the srcdoc, so the first paint is already
  // dark-correct and never flashes the un-themed email (see dark-email.ts).
  const safeHtml = sanitizeMessageDocument(next.html, null);
  const themedHtml = colorScheme === 'dark' ? adaptHtmlForDarkMode(safeHtml) : safeHtml;
  applyHtmlSrcDoc(themedHtml, colorScheme);
}

watch([body, bodyColorScheme], ([next, colorScheme]) => {
  renderHtmlBody(next, colorScheme);
}, { immediate: true });

watch(() => mailStore.selectedMessageId, () => {
  forceLightBody.value = false;
});

let openingDraftId: number | null = null;
watch([message, body], ([selected, selectedBody]) => {
  if (!selected || Number(selected.is_draft) !== 1 || !selectedBody) return;
  if (openingDraftId === selected.id) return;
  openingDraftId = selected.id;
  void composeStore.prepareDraftFromMessage(selected, selectedBody).then((sessionId) => {
    if (sessionId && mailStore.selectedMessageId === selected.id) {
      mailStore.selectMessage(null);
      mailStore.clearSelection();
    }
  }).finally(() => {
    if (openingDraftId === selected.id) openingDraftId = null;
  });
}, { immediate: true });

// Only offered in dark mode for HTML bodies; plain text already follows the
// readable app theme.
const canForceLightBody = computed(() =>
  effectiveColorScheme.value === 'dark' && !!iframeSrcDoc.value);

function toggleBodyLightMode() {
  forceLightBody.value = !forceLightBody.value;
}

function getEffectiveColorScheme() {
  if (typeof document !== 'undefined') {
    const root = document.documentElement;
    if (root.classList.contains('dark')) return 'dark';
    if (root.classList.contains('light')) return 'light';
  }

  if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
  }

  // The app's CSS defaults to dark unless a light preference/theme wins.
  return 'dark';
}

function updateEffectiveColorScheme() {
  effectiveColorScheme.value = getEffectiveColorScheme();
}

function teardownResizeObserver() {
  fitIframe = null;
  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
  iframeMeasurementCleanup?.();
  iframeMeasurementCleanup = null;
}

function teardownThemeObservers() {
  if (themeMediaQuery) {
    if (typeof themeMediaQuery.removeEventListener === 'function') {
      themeMediaQuery.removeEventListener('change', updateEffectiveColorScheme);
    } else if (typeof themeMediaQuery.removeListener === 'function') {
      themeMediaQuery.removeListener(updateEffectiveColorScheme);
    }
    themeMediaQuery = null;
  }

  if (themeMutationObserver) {
    themeMutationObserver.disconnect();
    themeMutationObserver = null;
  }
}

function initialIframeHeight() {
  return 120;
}

onMounted(() => {
  updateEffectiveColorScheme();

  if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    themeMediaQuery = window.matchMedia('(prefers-color-scheme: light)');
    if (typeof themeMediaQuery.addEventListener === 'function') {
      themeMediaQuery.addEventListener('change', updateEffectiveColorScheme);
    } else if (typeof themeMediaQuery.addListener === 'function') {
      themeMediaQuery.addListener(updateEffectiveColorScheme);
    }
  }

  if (typeof MutationObserver === 'function' && typeof document !== 'undefined') {
    themeMutationObserver = new MutationObserver(updateEffectiveColorScheme);
    themeMutationObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    });
  }
});

onUnmounted(() => {
  teardownResizeObserver();
  teardownThemeObservers();
  iframeSrcDoc.value = '';
});

function onIframeLoad() {
  teardownResizeObserver();
  const iframe = iframeRef.value;
  if (!iframe) return;
  const doc = iframe.contentDocument;
  if (!doc?.body) return;

  // Open links in a new tab. Without allow-scripts the iframe cannot
  // do navigation on its own anyway, but anchor clicks still bubble
  // up to the parent's default handling — which would replace the
  // whole webmail tab. target=_blank + rel=noopener fixes that.
  doc.querySelectorAll('a[href]').forEach((a) => {
    a.setAttribute('target', '_blank');
    a.setAttribute('rel', 'noopener noreferrer');
  });

  const onIframeKeyDown = (event: KeyboardEvent) => {
    onReadingKeyDown(event);
    invokeThunderbirdShortcut(event);
  };
  doc.addEventListener('keydown', onIframeKeyDown, true);

  let active = true;
  let rafScheduled = false;
  const docEl = doc.documentElement;
  const bodyEl = doc.body;

  // Apply a fit ratio against the *current* iframe viewport. We
  // deliberately re-measure on every call (and never observe the
  // iframe document directly): caching a "natural" width from one
  // viewport size and re-using it at another viewport produced
  // unpredictable zoom values for responsive content, because text
  // and other reflowable elements report scrollWidth == viewport at
  // the moment of measurement rather than their true min-content
  // width.
  //
  // Clearing `zoom` before measuring ensures scrollWidth reflects the
  // content's preferred width at the current viewport, independent of
  // any prior fit we applied. The browser only commits one frame per
  // animation tick, so the transient zoom=1 reset is not visible.
  //
  // The approach is the CSS `zoom` model used by Gmail's mobile web
  // viewer, not `transform: scale` from the host — `zoom` participates
  // in layout, so the iframe document's scaled metrics stay consistent
  // and a ResizeObserver scoped to the host shell does not feed back
  // on its own writes.
  const applyFit = () => {
    if (!active) return;
    const shellEl = htmlShellRef.value;
    const shellWidth = shellEl?.clientWidth ?? 0;
    if (shellWidth <= 0) return;
    docEl.style.zoom = '';
    const contentWidth = Math.max(
      docEl.scrollWidth,
      bodyEl.scrollWidth,
      1,
    );
    const bodyStyle = doc.defaultView?.getComputedStyle(bodyEl);
    const rootStyle = doc.defaultView?.getComputedStyle(docEl);
    const bottomSpace = [
      bodyStyle?.marginBottom,
      rootStyle?.paddingBottom,
      rootStyle?.borderBottomWidth,
      rootStyle?.marginBottom,
    ].reduce((total, value) => total + Math.max(0, Number.parseFloat(value ?? '') || 0), 0);
    const bodyTop = Math.max(0, bodyEl.getBoundingClientRect().top + (doc.defaultView?.scrollY ?? 0));
    const contentHeight = Math.max(
      bodyTop + Math.max(bodyEl.offsetHeight, bodyEl.scrollHeight) + bottomSpace,
      initialIframeHeight(),
    );
    // Clamp the effective content width: even if the document reflowed
    // to fit a very narrow viewport, fall back to MIN_EMAIL_LAYOUT_WIDTH
    // so the email still renders at a sensible layout size and zooms
    // down rather than reflowing into something cramped.
    const effectiveWidth = Math.max(contentWidth, MIN_EMAIL_LAYOUT_WIDTH);
    const ratio = effectiveWidth > shellWidth ? shellWidth / effectiveWidth : 1;
    docEl.style.zoom = ratio === 1 ? '' : String(ratio);
    const nextHeight = Math.max(120, Math.ceil(contentHeight * ratio));
    if (nextHeight !== iframeHeight.value) {
      iframeHeight.value = nextHeight;
    }
  };
  fitIframe = applyFit;

  // MDN guidance for ResizeObserver feedback safety: defer the
  // callback to a rAF and skip re-entrant scheduling.
  const scheduleApplyFit = () => {
    if (rafScheduled) return;
    rafScheduled = true;
    requestAnimationFrame(() => {
      rafScheduled = false;
      applyFit();
    });
  };

  applyFit();

  const cleanups: Array<() => void> = [];
  const scheduleApplyFitAfter = (delay: number | 'raf') => {
    if (delay === 'raf') {
      if (typeof requestAnimationFrame !== 'function') return;
      const id = requestAnimationFrame(applyFit);
      cleanups.push(() => cancelAnimationFrame(id));
      return;
    }
    const id = window.setTimeout(applyFit, delay);
    cleanups.push(() => clearTimeout(id));
  };

  // Late-arriving inline content (fonts, images, slow stylesheets) may
  // grow the iframe document after the initial measurement. Re-apply a
  // few times so the height and zoom settle correctly.
  scheduleApplyFitAfter('raf');
  scheduleApplyFitAfter(150);
  scheduleApplyFitAfter(600);

  for (const img of Array.from(doc.images ?? []) as HTMLImageElement[]) {
    if (img.complete) continue;
    img.addEventListener('load', applyFit, { once: true });
    img.addEventListener('error', applyFit, { once: true });
    cleanups.push(() => {
      img.removeEventListener('load', applyFit);
      img.removeEventListener('error', applyFit);
    });
  }

  if (doc.fonts?.ready) {
    doc.fonts.ready.then(applyFit).catch(() => {});
  }

  iframeMeasurementCleanup = () => {
    active = false;
    doc.removeEventListener('keydown', onIframeKeyDown, true);
    for (const cleanup of cleanups) cleanup();
  };

  if (typeof ResizeObserver === 'function' && htmlShellRef.value) {
    resizeObserver = new ResizeObserver(scheduleApplyFit);
    resizeObserver.observe(htmlShellRef.value);
  }
}

// Formatted against the fixed locale and time zone so every run renders
// the same text.
function fmtDate(ms) {
  if (!ms) return '';
  const d = new Date(Number(ms));
  return Number.isNaN(d.valueOf()) ? '' : d.toLocaleString(LOCALE, { timeZone: TIME_ZONE });
}

// Stormbox inlines the body's cid: images as data: URLs in the quote, so
// the send re-uploads them; generated bodies have none.
async function quoteBody() {
  return body.value ?? {};
}

async function reply() {
  if (!message.value) return;
  await composeStore.prepareReplyFromMessage(message.value, await quoteBody());
}

async function replyAll() {
  if (!message.value) return;
  await composeStore.prepareReplyAll(message.value, await quoteBody());
}

async function forward() {
  if (!message.value) return;
  composeStore.prepareForward(message.value, await quoteBody());
}

async function archive() {
  if (!message.value) return;
  try {
    await mailStore.archiveMessages([message.value.id], messageSource.value);
  } catch (err) {
    console.warn('[message-view] archive failed', err?.message ?? err);
  }
}

// Whitelisting only makes sense for messages currently in the Junk
// folder; the toolbar button is gated on this. Archiving from Archive
// is a no-op, so that button is gated the same way.
const isInJunkFolder = computed(() => mailStore.openMessageFolder?.role === 'junk');
const isInArchiveFolder = computed(() => mailStore.openMessageFolder?.role === 'archive');
const canWhitelistInJunk = computed(() => {
  const current = mailStore.openMessageFolder;
  return current?.role === 'junk'
    && mailStore.primaryFolders.some((folder) => folder.id === current.id);
});
const whitelisting = ref(false);

async function whitelistSender() {
  if (!message.value || whitelisting.value) return;
  whitelisting.value = true;
  try {
    await mailStore.whitelistSender(message.value.id, messageSource.value);
  } catch (err) {
    console.warn('[message-view] whitelist failed', err?.message ?? err);
  } finally {
    whitelisting.value = false;
  }
}

async function junk() {
  if (!message.value) return;
  try {
    await mailStore.junkMessages([message.value.id], messageSource.value);
  } catch (err) {
    console.warn('[message-view] junk failed', err?.message ?? err);
  }
}

// Send Later: a scheduled message renders through the normal detail
// view. While its submission is pending the toolbar is read-only and the
// banner owns Cancel Send; a settled row keeps the ordinary toolbar and
// only shows the banner while its filing handoff is in flight. Either
// way the Date row is labeled with the send time.
const scheduledStatus = computed(() => {
  const value = message.value?.scheduled_undo_status;
  return value === 'pending' || value === 'final' || value === 'canceled'
    ? value
    : null;
});
const hasScheduledBanner = computed(() => scheduledStatus.value != null);
const isPendingScheduled = computed(() => isScheduledMessage(message.value));
const cancelingScheduled = ref(false);

function describeTimeUntil(ms) {
  const target = Number(ms);
  if (!Number.isFinite(target)) return '';
  const diffMs = target - NOW;
  const rtf = new Intl.RelativeTimeFormat(LOCALE, { numeric: 'auto' });
  const minutes = Math.round(diffMs / 60_000);
  if (Math.abs(minutes) < 60) return rtf.format(minutes, 'minute');
  const hours = Math.round(diffMs / 3_600_000);
  if (Math.abs(hours) < 48) return rtf.format(hours, 'hour');
  return rtf.format(Math.round(diffMs / 86_400_000), 'day');
}

const scheduledBannerText = computed(() => {
  const sendAt = message.value?.sent_at;
  switch (scheduledStatus.value) {
    case 'pending': {
      const relative = describeTimeUntil(sendAt);
      return `Scheduled to send ${fmtDate(sendAt)}${relative ? ` (${relative})` : ''}.`;
    }
    case 'final':
      return 'This message was sent and is moving to your Sent folder.';
    case 'canceled':
      return 'Sending was canceled; this message is moving back to Drafts.';
    default:
      return '';
  }
});

async function cancelScheduledSend() {
  if (!message.value || cancelingScheduled.value) return;
  cancelingScheduled.value = true;
  try {
    await mailStore.cancelScheduledSend(message.value.id);
  } catch (err) {
    console.warn('[message-view] cancel scheduled send failed', err?.message ?? err);
  } finally {
    cancelingScheduled.value = false;
  }
}

async function destroy() {
  if (!message.value) return;
  try {
    await mailStore.destroyMessage(message.value.id, messageSource.value);
  } catch (err) {
    // The store has already populated mailStore.error with a
    // human-readable string in describeMutationFailure. Suppress the
    // unhandled-rejection so Vue does not log "Unhandled error during
    // execution of native event handler"; we have already surfaced
    // the failure to the user via mailStore.error.
    console.warn('[message-view] delete failed', err?.message ?? err);
  }
}

function closeMessageView() {
  mailStore.selectMessage(null);
  mailStore.clearSelection();
}
</script>

