<script setup lang="ts">
/**
 * The markup of @thunderbirdops/services-ui's PrimaryButton (its
 * BaseButton with the `primary` type), which AppButton wraps. The
 * package's stylesheet styles every services-ui component; this build
 * carries only the tokens and button rules (styles/services-ui.css).
 */
withDefaults(
  defineProps<{
    variant?: 'filled' | 'outline';
    formAction?: 'none' | 'submit' | 'reset';
    disabled?: boolean;
  }>(),
  { variant: 'filled', formAction: 'none', disabled: false },
);
</script>

<template>
  <button
    class="base primary"
    :class="variant"
    :type="formAction === 'none' ? 'button' : formAction"
    :disabled="disabled"
    data-testid="button"
  >
    <span v-if="$slots.iconLeft" class="icon"><slot name="iconLeft" /></span>
    <span class="text"><slot /></span>
    <span v-if="$slots.iconRight" class="icon"><slot name="iconRight" /></span>
  </button>
</template>
