/**
 * Compose sessions with the API of Stormbox's compose-store.
 *
 * Stormbox saves drafts and sends through its outbox (Email/set and
 * EmailSubmission/set, with autosave and attachment uploads). Here a
 * send files the message in Sent (or Scheduled) at once and a save files
 * it in Drafts, as stormbox-react's compose store does. Addressing and
 * quoting use Stormbox's own helpers (reply.ts, compose-quote.ts,
 * compose-provenance.ts).
 */

import { defineStore } from 'pinia';
import { computed, reactive, ref } from 'vue';

import { NOW } from '../clock';
import { COMPOSE_STATE, type ComposeState } from '../constants/states';
import { IDENTITIES } from '../data/mailbox';
import type { IdentityRow, Message, MessageRow } from '../types';
import { addressKey } from '../utils/address-key';
import { formatAddress, type ParsedAddress } from '../utils/address-parse';
import { editSafeDraftHtml } from '../utils/compose-html';
import { stripInternalProvenanceHtml, wrapQuotedContent } from '../utils/compose-provenance';
import {
  buildQuotedHtml, buildQuotedText, makeForwardSubject, makeReplySubject,
} from '../utils/compose-quote';
import { buildReplyAudience } from '../utils/reply';
import { formatScheduleTarget } from '../utils/schedule-time';
import {
  DRAFTS_FOLDER_ID, SCHEDULED_FOLDER_ID, SENT_FOLDER_ID, messageAddresses, useMailStore,
} from './mail-store';

export type RecipientField = 'to' | 'cc' | 'bcc';

export const RECIPIENT_FIELDS: readonly RecipientField[] = ['to', 'cc', 'bcc'];
export const INVALID_RECIPIENT_MESSAGE =
  'Fix invalid recipients before saving or sending this message.';
const NO_RECIPIENT_MESSAGE = 'Add at least one recipient before sending.';

/**
 * Text a user committed as a recipient that is not a readable address.
 * It stays where it was entered, marked, and refuses the send until it
 * is fixed.
 */
export interface InvalidRecipient {
  text: string;
  invalid: true;
}

/** One committed recipient: an address, or text that is not one. */
export type RecipientEntry = ParsedAddress | InvalidRecipient;

export interface Draft {
  fromIdx: number;
  to: ParsedAddress[];
  cc: ParsedAddress[];
  bcc: ParsedAddress[];
  subject: string;
  textBody: string;
  htmlBody: string;
}

type DraftPrefill = Partial<Draft>;

function emptyDraft(): Draft {
  return {
    fromIdx: 0,
    to: [],
    cc: [],
    bcc: [],
    subject: '',
    textBody: '',
    htmlBody: '',
  };
}

export const COMPOSE_PRESENTATION = {
  EXPANDED: 'expanded',
  MINIMIZED: 'minimized',
  /** Off screen while its send is in flight (never, here: sends complete at once). */
  HIDDEN: 'hidden',
} as const;

export type ComposePresentation =
  (typeof COMPOSE_PRESENTATION)[keyof typeof COMPOSE_PRESENTATION];

export const COMPOSE_OPEN_ORIGIN = {
  NEW: 'new',
  REPLY: 'reply',
  REPLY_ALL: 'reply-all',
  FORWARD: 'forward',
  SERVER_DRAFT: 'server-draft',
} as const;

export type ComposeOpenOrigin =
  (typeof COMPOSE_OPEN_ORIGIN)[keyof typeof COMPOSE_OPEN_ORIGIN];

export interface ComposeSession {
  id: string;
  presentation: ComposePresentation;
  status: ComposeState;
  sendingScheduledAt: string | null;
  dockedSendFailure: boolean;
  error: string | null;
  saveError: string | null;
  isSaving: boolean;
  isDiscarding: boolean;
  closePromptOpen: boolean;
  draft: Draft;
  recipientEntriesByField: Record<RecipientField, RecipientEntry[]>;
  rejectedRecipients: Record<RecipientField, string[]>;
  pendingRecipientText: Record<RecipientField, string>;
  /** Bumped when the draft is replaced wholesale; remounts the recipient fields. */
  draftEpoch: number;
  /** The Drafts message this session edits, replaced on save and removed on send. */
  sourceMessageId: number | null;
  unresolvedFrom: ParsedAddress | null;
  openOrigin: ComposeOpenOrigin;
  /** HTML the editor starts from. */
  editorHtmlBody: string;
  bodyVersion: number;
  recipientVersion: number;
}

/** The session's name in the dock and the send toast: subject, then first recipient, then “New message”. */
export function sessionLabel(session: ComposeSession): string {
  const subject = session.draft.subject.trim();
  if (subject) return subject;
  const recipient = session.draft.to[0] ?? session.draft.cc[0] ?? session.draft.bcc[0];
  return recipient?.name?.trim() || recipient?.email || 'New message';
}

function cloneDraft(prefill: DraftPrefill = {}): Draft {
  return {
    ...emptyDraft(),
    ...prefill,
    to: [...(prefill.to ?? [])].map((entry) => ({ ...entry })),
    cc: [...(prefill.cc ?? [])].map((entry) => ({ ...entry })),
    bcc: [...(prefill.bcc ?? [])].map((entry) => ({ ...entry })),
  };
}

function editorHtmlForOpen(html: string, origin: ComposeOpenOrigin): string {
  const clean = stripInternalProvenanceHtml(html);
  switch (origin) {
    case COMPOSE_OPEN_ORIGIN.NEW:
    case COMPOSE_OPEN_ORIGIN.SERVER_DRAFT:
      return clean;
    case COMPOSE_OPEN_ORIGIN.REPLY:
    case COMPOSE_OPEN_ORIGIN.REPLY_ALL:
    case COMPOSE_OPEN_ORIGIN.FORWARD:
      return clean ? `<div><br></div>${wrapQuotedContent(clean)}` : clean;
    default: {
      const exhaustive: never = origin;
      throw new Error(`Unhandled compose open origin: ${String(exhaustive)}`);
    }
  }
}

/** Plain text as editor markup: escaped, with line breaks kept as <br>. */
function textToEditorHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');
}

let sessionCounter = 0;
/** Composed mail is stamped after the fixed clock so it sorts above generated mail. */
let composeClock = NOW;

function nextTimestamp(): number {
  composeClock += 60_000;
  return composeClock;
}

/** Longest Send Later delay offered, in seconds (a month). */
const MAX_DELAYED_SEND = 30 * 24 * 60 * 60;

export const useComposeStore = defineStore('compose', () => {
  const mailStore = useMailStore();

  const sessions = ref<ComposeSession[]>([]);
  const activeSessionId = ref<string | null>(null);
  const identities = ref<IdentityRow[]>(IDENTITIES.map((identity) => ({ ...identity })));
  const fallbackDraft = reactive<Draft>(emptyDraft());
  const fallbackError = ref<string | null>(null);

  const scheduleCapability = ref({
    supported: true,
    maxDelayedSend: MAX_DELAYED_SEND,
    serverClockReference: null,
  });
  const scheduleCapabilityKnown = computed(() => true);
  const canScheduleSend = computed(() => scheduleCapability.value.supported);
  const scheduleMaxDelayedSend = computed(() => scheduleCapability.value.maxDelayedSend);

  function sessionById(id: string | null | undefined): ComposeSession | null {
    if (!id) return null;
    return sessions.value.find((session) => session.id === id) ?? null;
  }

  const activeSession = computed(() => sessionById(activeSessionId.value));
  const isOpen = computed(() => sessions.value.length > 0);
  const isExpanded = computed(() => activeSession.value?.presentation === COMPOSE_PRESENTATION.EXPANDED);
  const draft = computed(() => activeSession.value?.draft ?? fallbackDraft);
  const error = computed<string | null>({
    get: () => activeSession.value?.error ?? fallbackError.value,
    set: (value) => {
      const session = activeSession.value;
      if (session) session.error = value;
      else fallbackError.value = value;
    },
  });

  // Transient send confirmation, rendered by StoreErrorToast after the
  // dialog has closed.
  const notice = ref<string | null>(null);
  let noticeTimer: ReturnType<typeof setTimeout> | null = null;

  function setNotice(message: string): void {
    notice.value = message;
    if (noticeTimer) clearTimeout(noticeTimer);
    noticeTimer = setTimeout(() => {
      notice.value = null;
      noticeTimer = null;
    }, 5000);
  }

  function clearNotice(): void {
    if (noticeTimer) clearTimeout(noticeTimer);
    noticeTimer = null;
    notice.value = null;
  }

  function identityForSession(session: ComposeSession | null | undefined): IdentityRow | null {
    const idx = session?.draft.fromIdx ?? 0;
    return identities.value[idx] ?? identities.value[0] ?? null;
  }

  function ownedEmails(): string[] {
    return identities.value.map((identity) => identity.email);
  }

  /** The identity a reply is sent from: the first one the parent was addressed to. */
  function replyFromIdx(preferredIdentityEmails: readonly string[]): number {
    for (const email of preferredIdentityEmails) {
      const idx = identities.value.findIndex((identity) => addressKey(identity.email) === addressKey(email));
      if (idx >= 0) return idx;
    }
    return 0;
  }

  function open(
    prefill: DraftPrefill = {},
    options: { origin: ComposeOpenOrigin; preferredIdentityEmails?: string[] } = { origin: COMPOSE_OPEN_ORIGIN.NEW },
  ): string {
    const expanded = activeSession.value;
    if (expanded) expanded.presentation = COMPOSE_PRESENTATION.MINIMIZED;
    const nextDraft = cloneDraft(prefill);
    if (!Object.prototype.hasOwnProperty.call(prefill, 'fromIdx')) {
      nextDraft.fromIdx = replyFromIdx(options.preferredIdentityEmails ?? []);
    }
    const initialEditorHtml = editorHtmlForOpen(nextDraft.htmlBody, options.origin);
    nextDraft.htmlBody = stripInternalProvenanceHtml(initialEditorHtml);
    sessionCounter += 1;
    const id = `compose-${sessionCounter}`;
    const session: ComposeSession = reactive({
      id,
      presentation: COMPOSE_PRESENTATION.EXPANDED,
      status: COMPOSE_STATE.EDITING,
      sendingScheduledAt: null,
      dockedSendFailure: false,
      error: null,
      saveError: null,
      isSaving: false,
      isDiscarding: false,
      closePromptOpen: false,
      draft: nextDraft,
      recipientEntriesByField: {
        to: nextDraft.to.map((entry) => ({ ...entry })),
        cc: nextDraft.cc.map((entry) => ({ ...entry })),
        bcc: nextDraft.bcc.map((entry) => ({ ...entry })),
      },
      rejectedRecipients: { to: [], cc: [], bcc: [] },
      pendingRecipientText: { to: '', cc: '', bcc: '' },
      draftEpoch: 1,
      sourceMessageId: null,
      unresolvedFrom: null,
      openOrigin: options.origin,
      editorHtmlBody: initialEditorHtml,
      bodyVersion: 0,
      recipientVersion: 0,
    });
    sessions.value.push(session);
    activeSessionId.value = id;
    clearNotice();
    return id;
  }

  function close(sessionId: string | null = activeSessionId.value): boolean {
    const session = sessionById(sessionId);
    if (!session) return true;
    sessions.value = sessions.value.filter((candidate) => candidate.id !== session.id);
    if (activeSessionId.value === session.id) activeSessionId.value = null;
    return true;
  }

  function minimize(sessionId: string | null = activeSessionId.value): boolean {
    const session = sessionById(sessionId);
    if (!session) return false;
    session.presentation = COMPOSE_PRESENTATION.MINIMIZED;
    session.closePromptOpen = false;
    if (activeSessionId.value === session.id) activeSessionId.value = null;
    return true;
  }

  function restore(sessionId: string): boolean {
    const session = sessionById(sessionId);
    if (!session) return false;
    session.dockedSendFailure = false;
    const expanded = activeSession.value;
    if (expanded?.id === session.id) return true;
    if (expanded) expanded.presentation = COMPOSE_PRESENTATION.MINIMIZED;
    session.presentation = COMPOSE_PRESENTATION.EXPANDED;
    activeSessionId.value = session.id;
    return true;
  }

  function dismissSendFailureNotice(sessionId: string): void {
    const session = sessionById(sessionId);
    if (session) session.dockedSendFailure = false;
  }

  function selectFromIndex(value: number | string, sessionId: string | null = activeSessionId.value): void {
    const session = sessionById(sessionId);
    if (!session) return;
    const parsed = typeof value === 'number' ? value : Number(value);
    const maxIdx = identities.value.length - 1;
    session.draft.fromIdx = Number.isFinite(parsed)
      ? Math.min(Math.max(Math.trunc(parsed), 0), Math.max(maxIdx, 0))
      : 0;
    session.unresolvedFrom = null;
  }

  /** Replace a field's entries; the draft keeps the addresses, duplicates across fields dropped. */
  function setRecipientEntries(
    field: RecipientField,
    entries: readonly RecipientEntry[],
    sessionId: string | null = activeSessionId.value,
  ): void {
    const session = sessionById(sessionId);
    if (!session) return;
    const seen = new Set<string>();
    for (const other of RECIPIENT_FIELDS) {
      if (other === field) continue;
      for (const entry of session.recipientEntriesByField[other]) {
        if ('email' in entry) seen.add(addressKey(entry.email));
      }
    }
    const normalized: RecipientEntry[] = [];
    for (const entry of entries) {
      if ('invalid' in entry) {
        normalized.push({ ...entry });
        continue;
      }
      const key = addressKey(entry.email);
      if (seen.has(key)) continue;
      seen.add(key);
      normalized.push({ ...entry });
    }
    session.recipientEntriesByField[field] = normalized;
    session.draft[field] = normalized
      .filter((entry): entry is ParsedAddress => 'email' in entry)
      .map((entry) => ({ ...entry }));
    session.rejectedRecipients[field] = normalized
      .filter((entry): entry is InvalidRecipient => 'invalid' in entry)
      .map((entry) => entry.text);
    if (RECIPIENT_FIELDS.every((name) => session.rejectedRecipients[name].length === 0)
        && session.error === INVALID_RECIPIENT_MESSAGE) {
      session.error = null;
    }
  }

  function setPendingRecipientText(
    field: RecipientField,
    value: string,
    sessionId: string | null = activeSessionId.value,
  ): void {
    const session = sessionById(sessionId);
    if (session) session.pendingRecipientText[field] = value;
  }

  function recipientEntries(field: RecipientField, sessionId: string | null = activeSessionId.value): RecipientEntry[] {
    const session = sessionById(sessionId);
    if (!session) return [];
    return session.recipientEntriesByField[field].map((entry) => ({ ...entry }));
  }

  function setBodyContent(
    content: { html: string; text: string },
    sessionId: string | null = activeSessionId.value,
    _options: { touch?: boolean } = {},
  ): void {
    const session = sessionById(sessionId);
    if (!session) return;
    session.editorHtmlBody = content.html;
    session.draft.htmlBody = stripInternalProvenanceHtml(content.html);
    session.draft.textBody = content.text;
  }

  /** Stormbox schedules an autosave here; this build saves only when asked. */
  function touchSession(_sessionId: string | null = activeSessionId.value): void {}

  /** Stormbox tracks the identity signature's provenance here; this build has no signatures. */
  function updateTrackedOrigins(_states: unknown, _sessionId: string | null = activeSessionId.value): void {}

  /** Whether closing would lose anything: a recipient, pending text, a subject or body text. */
  function isSessionMeaningfullyNonEmpty(sessionId: string | null = activeSessionId.value): boolean {
    const session = sessionById(sessionId);
    if (!session) return false;
    const hasRecipients = RECIPIENT_FIELDS.some((field) =>
      session.draft[field].length > 0
      || session.rejectedRecipients[field].length > 0
      || session.pendingRecipientText[field].trim().length > 0);
    const htmlText = stripInternalProvenanceHtml(session.editorHtmlBody)
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;|&#160;/gi, ' ')
      .trim();
    return hasRecipients
      || session.draft.subject.trim().length > 0
      || session.draft.textBody.trim().length > 0
      || htmlText.length > 0;
  }

  function requestClose(sessionId: string | null = activeSessionId.value): boolean {
    const session = sessionById(sessionId);
    if (!session) return false;
    if (!isSessionMeaningfullyNonEmpty(session.id)) return close(session.id);
    if (session.presentation !== COMPOSE_PRESENTATION.EXPANDED) restore(session.id);
    session.closePromptOpen = true;
    return false;
  }

  function cancelClose(sessionId: string | null = activeSessionId.value): void {
    const session = sessionById(sessionId);
    if (session) session.closePromptOpen = false;
  }

  function messageFromSession(
    session: ComposeSession,
    folderId: number,
    extra: Partial<Message> = {},
  ): Omit<Message, 'id'> {
    const identity = identityForSession(session) ?? identities.value[0];
    const from: ParsedAddress = identity.name ? { name: identity.name, email: identity.email } : { email: identity.email };
    const at = nextTimestamp();
    const { draft: current } = session;
    return {
      folder_id: folderId,
      from_text: formatAddress(from),
      to_text: current.to.map(formatAddress).join(', '),
      cc: current.cc.map((address) => ({ ...address })),
      subject: current.subject,
      preview: current.textBody.replace(/\s+/g, ' ').trim().slice(0, 180),
      received_at: at,
      sent_at: at,
      is_seen: 1,
      is_flagged: 0,
      is_draft: folderId === DRAFTS_FOLDER_ID ? 1 : 0,
      has_attachment: 0,
      keywords_json: '{}',
      scheduled_undo_status: null,
      body_kind: 'html',
      body_seed: 0,
      body: { html: current.htmlBody || '<p><br></p>', text: current.textBody, attachments: [] },
      ...extra,
    };
  }

  /** File the session in Drafts, replacing the draft it was opened from. */
  async function saveAndClose(sessionId: string | null = activeSessionId.value): Promise<boolean> {
    const session = sessionById(sessionId);
    if (!session) return false;
    if (session.sourceMessageId != null) mailStore.removeMessage(session.sourceMessageId);
    mailStore.addMessage(messageFromSession(session, DRAFTS_FOLDER_ID));
    close(session.id);
    setNotice('Draft saved.');
    return true;
  }

  async function closeWithoutSaving(sessionId: string | null = activeSessionId.value): Promise<boolean> {
    return close(sessionId);
  }

  async function discardDraft(sessionId: string | null = activeSessionId.value): Promise<boolean> {
    const session = sessionById(sessionId);
    if (!session) return false;
    if (session.sourceMessageId != null) mailStore.removeMessage(session.sourceMessageId);
    return close(session.id);
  }

  /** Whether the session can go out; sets its error when not. */
  function readyToSend(session: ComposeSession): boolean {
    if (RECIPIENT_FIELDS.some((field) => session.rejectedRecipients[field].length > 0)) {
      session.error = INVALID_RECIPIENT_MESSAGE;
      return false;
    }
    if (RECIPIENT_FIELDS.every((field) => session.draft[field].length === 0)) {
      session.error = NO_RECIPIENT_MESSAGE;
      return false;
    }
    session.error = null;
    return true;
  }

  async function send(sessionId: string | null = activeSessionId.value): Promise<boolean> {
    const session = sessionById(sessionId);
    if (!session || !readyToSend(session)) return false;
    if (session.sourceMessageId != null) mailStore.removeMessage(session.sourceMessageId);
    mailStore.addMessage(messageFromSession(session, SENT_FOLDER_ID));
    close(session.id);
    setNotice('Message sent.');
    return true;
  }

  async function scheduleSend(sessionId: string, targetAt: string, timeZone: string): Promise<boolean> {
    const session = sessionById(sessionId);
    if (!session || !readyToSend(session)) return false;
    if (session.sourceMessageId != null) mailStore.removeMessage(session.sourceMessageId);
    mailStore.addMessage(messageFromSession(session, SCHEDULED_FOLDER_ID, {
      sent_at: Date.parse(targetAt),
      scheduled_undo_status: 'pending',
    }));
    close(session.id);
    setNotice(`Message scheduled for ${formatScheduleTarget(targetAt, timeZone)}.`);
    return true;
  }

  async function prepareReplyToMessage(
    message: MessageRow,
    body: { html?: string | null; text?: string | null },
    all: boolean,
  ): Promise<void> {
    const addresses = messageAddresses(message);
    const audience = buildReplyAudience({ addresses, ownedEmails: ownedEmails(), all });
    const preferredIdentityEmails = addresses
      .filter((address) => address.kind === 'to' && address.email)
      .sort((left, right) => left.position - right.position)
      .map((address) => address.email as string);
    open({
      to: audience.to,
      cc: audience.cc,
      subject: makeReplySubject(message.subject),
      htmlBody: buildQuotedHtml({
        from: message.from_text,
        date: message.received_at,
        subject: message.subject,
        html: body.html,
        text: body.text,
      }),
      textBody: buildQuotedText({
        from: message.from_text,
        date: message.received_at,
        subject: message.subject,
        text: body.text,
      }),
    }, {
      origin: all ? COMPOSE_OPEN_ORIGIN.REPLY_ALL : COMPOSE_OPEN_ORIGIN.REPLY,
      preferredIdentityEmails,
    });
  }

  function prepareReplyFromMessage(
    message: MessageRow,
    body: { html?: string | null; text?: string | null } = {},
  ): Promise<void> {
    return prepareReplyToMessage(message, body, false);
  }

  function prepareReplyAll(
    message: MessageRow,
    body: { html?: string | null; text?: string | null } = {},
  ): Promise<void> {
    return prepareReplyToMessage(message, body, true);
  }

  function prepareForward(
    message: Pick<MessageRow, 'from_text' | 'subject' | 'received_at'>,
    body: { html?: string | null; text?: string | null } = {},
  ): void {
    open({
      subject: makeForwardSubject(message.subject),
      htmlBody: buildQuotedHtml({
        from: message.from_text,
        date: message.received_at,
        subject: message.subject,
        html: body.html,
        text: body.text,
      }),
      textBody: buildQuotedText({
        from: message.from_text,
        date: message.received_at,
        subject: message.subject,
        text: body.text,
      }),
    }, { origin: COMPOSE_OPEN_ORIGIN.FORWARD });
  }

  /** Open a Drafts message for editing; an open session for it is restored instead. */
  async function prepareDraftFromMessage(
    message: MessageRow,
    body: { html?: string | null; text?: string | null } = {},
  ): Promise<string | null> {
    const existing = sessions.value.find((session) => session.sourceMessageId === message.id);
    if (existing) return restore(existing.id) ? existing.id : null;
    const addresses = messageAddresses(message);
    const byKind = (kind: RecipientField) => addresses
      .filter((row) => row.kind === kind && row.email)
      .sort((left, right) => left.position - right.position)
      .map((row) => ({ ...(row.name ? { name: row.name } : {}), email: row.email as string }));
    const from = addresses.find((row) => row.kind === 'from' && row.email);
    const fromKey = addressKey(from?.email);
    const fromIdx = fromKey
      ? identities.value.findIndex((identity) => addressKey(identity.email) === fromKey)
      : -1;
    const html = body.html ? editSafeDraftHtml(body.html) : textToEditorHtml(body.text ?? '');
    const sessionId = open({
      ...(fromIdx >= 0 ? { fromIdx } : {}),
      to: byKind('to'),
      cc: byKind('cc'),
      bcc: byKind('bcc'),
      subject: message.subject ?? '',
      textBody: body.text ?? '',
      htmlBody: html,
    }, { origin: COMPOSE_OPEN_ORIGIN.SERVER_DRAFT });
    const session = sessionById(sessionId);
    if (!session) return null;
    session.sourceMessageId = message.id;
    return session.id;
  }

  return {
    sessions,
    activeSessionId,
    activeSession,
    identities,
    isOpen,
    isExpanded,
    draft,
    error,
    notice,
    scheduleCapability,
    scheduleCapabilityKnown,
    canScheduleSend,
    scheduleMaxDelayedSend,
    sessionById,
    identityForSession,
    open,
    close,
    minimize,
    restore,
    dismissSendFailureNotice,
    selectFromIndex,
    setRecipientEntries,
    setPendingRecipientText,
    recipientEntries,
    setBodyContent,
    touchSession,
    updateTrackedOrigins,
    isSessionMeaningfullyNonEmpty,
    requestClose,
    cancelClose,
    saveAndClose,
    closeWithoutSaving,
    discardDraft,
    send,
    scheduleSend,
    prepareReplyFromMessage,
    prepareReplyAll,
    prepareForward,
    prepareDraftFromMessage,
    clearNotice,
  };
});
