/**
 * The signed-in account. Stormbox gets it from OIDC and the JMAP
 * session; here it is the generated mailbox's owner, with a fixed
 * storage quota for the sidebar's usage bar.
 */

import { defineStore } from 'pinia';
import { computed } from 'vue';

import { ACCOUNT } from '../data/mailbox';

const QUOTA_BYTES = 30 * 1024 ** 3;
const USED_BYTES = Math.round(QUOTA_BYTES * 0.37);

export const useAuthStore = defineStore('auth', () => {
  const username = ACCOUNT.email;
  const serverHostname = '';
  const quotaHardLimitBytes = QUOTA_BYTES;
  const quotaUsedBytes = USED_BYTES;
  const hasStorageQuota = true;
  const storagePercentUsed = computed(() => Math.round((quotaUsedBytes / quotaHardLimitBytes) * 100));
  const storageProgressWidth = computed(() => `${storagePercentUsed.value}%`);

  function logout() {}

  return {
    username,
    serverHostname,
    quotaHardLimitBytes,
    quotaUsedBytes,
    hasStorageQuota,
    storagePercentUsed,
    storageProgressWidth,
    logout,
  };
});
