/**
 * Mail data store with the API of Stormbox's mail-store, over an
 * in-memory mailbox generated from a fixed seed.
 *
 * Stormbox reads folders and messages through a SQLite repository in a
 * SharedWorker and writes through an outbox of JMAP mutations; here
 * every mutation applies at once. The mailbox lives in `shallowRef`s
 * and is replaced, never mutated, on each change (the same immutable
 * updates stormbox-react's Zustand store makes), so a change re-derives
 * the folder views and counts that read it.
 *
 * A folder view is the whole folder: there are no pages to fetch, so the
 * window-loading calls Stormbox's list makes are not part of this API.
 */

import { defineStore } from 'pinia';
import {
  computed, markRaw, ref, shallowRef,
} from 'vue';

import { bodyFor } from '../data/bodies';
import { generateMailbox, type Contact } from '../data/mailbox';
import type { JmapViewSort, MailboxRole } from '../constants/states';
import type {
  Folder, FolderRow, Message, MessageBody,
} from '../types';
import { parseAddressList } from '../utils/address-parse';
import {
  isTagKeyword, normalizeKeyword, resolveTag,
} from '../utils/message-tags';
import type { MessageAddress } from '../utils/reply';
import { isScheduledMessage } from '../utils/scheduled-message';
import { useSettingsStore } from './settings-store';
import type { CachedRow, FolderView } from './mail-store-types';

export const STARRED_KEYWORD = '$flagged';
export const INBOX_FOLDER_ID = 1;
export const DRAFTS_FOLDER_ID = 2;
export const SCHEDULED_FOLDER_ID = 3;
export const SENT_FOLDER_ID = 4;
export const ARCHIVE_FOLDER_ID = 5;
export const JUNK_FOLDER_ID = 6;
export const TRASH_FOLDER_ID = 7;

/** Folders a tag view leaves out: their mail is on its way out. */
const TAG_VIEW_EXCLUDED = new Set([JUNK_FOLDER_ID, TRASH_FOLDER_ID]);
/** Tag views are addressed like folders, by ids at or below this one (as in Stormbox). */
const TAG_VIEW_ID_BASE = -1_000_000;

interface BulkSourceOptions {
  sourceFolderId?: number | null;
  rows?: ReadonlyArray<CachedRow | undefined>;
}

interface SharedAccount {
  id: number;
  display_name: string | null;
  primary_email: string | null;
}

interface Attributed {
  id: number | null;
  folderId: number | null;
}

/** Messages per folder and per tag, derived once per mailbox snapshot. */
interface MailboxCounts {
  unread: Map<number, number>;
  total: Map<number, number>;
  /** Messages carrying each tag keyword (and $flagged), outside Junk and Trash. */
  tags: Map<string, number>;
}

function parseKeywords(message: Message): Record<string, boolean> {
  if (!message.keywords_json || message.keywords_json === '{}') return {};
  try {
    return JSON.parse(message.keywords_json) as Record<string, boolean>;
  } catch {
    return {};
  }
}

function messageHasKeyword(message: Message, keyword: string): boolean {
  if (keyword === STARRED_KEYWORD) return message.is_flagged === 1;
  const parsed = parseKeywords(message);
  return Object.keys(parsed).some((key) => parsed[key] === true && normalizeKeyword(key) === keyword);
}

function countMailbox(messages: ReadonlyMap<number, Message>): MailboxCounts {
  const unread = new Map<number, number>();
  const total = new Map<number, number>();
  const tags = new Map<string, number>();
  for (const message of messages.values()) {
    total.set(message.folder_id, (total.get(message.folder_id) ?? 0) + 1);
    if (message.is_seen === 0) unread.set(message.folder_id, (unread.get(message.folder_id) ?? 0) + 1);
    if (TAG_VIEW_EXCLUDED.has(message.folder_id)) continue;
    if (message.is_flagged === 1) tags.set(STARRED_KEYWORD, (tags.get(STARRED_KEYWORD) ?? 0) + 1);
    const parsed = parseKeywords(message);
    for (const key of Object.keys(parsed)) {
      if (parsed[key] !== true) continue;
      const keyword = normalizeKeyword(key);
      tags.set(keyword, (tags.get(keyword) ?? 0) + 1);
    }
  }
  return { unread, total, tags };
}

const sortNewestFirst = (messages: ReadonlyMap<number, Message>) => (a: number, b: number) =>
  (messages.get(b)!.received_at - messages.get(a)!.received_at) || (b - a);

/** Replace the messages `update` changes; the same map back when nothing did. */
function updateMessages(
  messages: Map<number, Message>,
  ids: Iterable<number>,
  update: (message: Message) => Message,
): Map<number, Message> {
  let next: Map<number, Message> | null = null;
  for (const id of ids) {
    const current = messages.get(id);
    if (!current) continue;
    const changed = update(current);
    if (changed === current) continue;
    next ??= new Map(messages);
    next.set(id, changed);
  }
  return next ?? messages;
}

function withKeywords(message: Message, change: (keywords: Record<string, boolean>) => void): Message {
  const parsed = { ...parseKeywords(message) };
  const before = JSON.stringify(parsed);
  change(parsed);
  const after = JSON.stringify(parsed);
  return before === after ? message : { ...message, keywords_json: after };
}

function addressRows(kind: string, text: string | null | undefined): MessageAddress[] {
  return parseAddressList(text ?? '').addresses.map((address, position) => ({
    kind, position, name: address.name ?? null, email: address.email,
  }));
}

/** A message's addresses one per row, as Stormbox's message_addresses table holds them. */
export function messageAddresses(message: Message): MessageAddress[] {
  return [
    ...addressRows('from', message.from_text),
    ...addressRows('to', message.to_text),
    ...message.cc.map((address, position) => ({
      kind: 'cc', position, name: address.name ?? null, email: address.email,
    })),
  ];
}

function initialMailbox() {
  const params = typeof location === 'undefined' ? null : new URLSearchParams(location.search);
  const scale = Math.max(0.01, Number(params?.get('scale') ?? 1) || 1);
  const mailbox = generateMailbox(scale);
  const messages = new Map<number, Message>();
  const folderIds = new Map<number, number[]>();
  for (const folder of mailbox.folders) folderIds.set(folder.id, []);
  for (const message of mailbox.messages) {
    messages.set(message.id, message);
    folderIds.get(message.folder_id)!.push(message.id);
  }
  const compare = sortNewestFirst(messages);
  for (const ids of folderIds.values()) ids.sort(compare);
  return {
    folders: mailbox.folders, messages, folderIds, contacts: mailbox.contacts,
  };
}

export const useMailStore = defineStore('mail', () => {
  const settingsStore = useSettingsStore();
  const initial = initialMailbox();

  const baseFolders: readonly Folder[] = markRaw(initial.folders);
  const contacts: Contact[] = markRaw(initial.contacts);
  const messages = shallowRef(initial.messages);
  /** Message ids per folder, newest first. */
  const folderIds = shallowRef(initial.folderIds);

  /**
   * Folder of the primary message list column: what the folder list
   * highlights and what `selectFolder` sets.
   */
  const currentFolderId = ref<number | null>(INBOX_FOLDER_ID);
  /**
   * Bumped by every `selectFolder`, re-picks included, so the list can
   * react to the same folder being chosen again.
   */
  const folderPickCount = ref(0);

  const counts = computed(() => countMailbox(messages.value));

  const folders = computed<FolderRow[]>(() => {
    const { unread, total } = counts.value;
    return baseFolders.map((folder) => ({
      ...folder,
      total_emails: total.get(folder.id) ?? 0,
      unread_emails: unread.get(folder.id) ?? 0,
    }));
  });
  /** Every folder belongs to the signed-in account, and all are subscribed. */
  const primaryFolders = folders;
  const sidebarPrimaryFolders = folders;
  /** Tag counts for the sidebar's Tags section. */
  const tagCounts = computed(() => counts.value.tags);

  // ----- tag views ---------------------------------------------------------
  // A tag view lists every message carrying one keyword, across folders
  // (Junk and Trash excepted). It is addressed like a folder by a negative
  // id, so the list, selection, cursor and open message bind to it
  // unchanged; folderById answers with a synthetic row named after the tag.

  const tagViewIdsByKeyword = new Map<string, number>();
  const tagViewKeywordsById = new Map<number, string>();

  function isTagViewId(folderId: number | string | null | undefined): boolean {
    const id = Number(folderId);
    return folderId != null && Number.isFinite(id) && id <= TAG_VIEW_ID_BASE;
  }

  function tagViewIdFor(keyword: string): number {
    const normalized = normalizeKeyword(keyword);
    const existing = tagViewIdsByKeyword.get(normalized);
    if (existing != null) return existing;
    const id = TAG_VIEW_ID_BASE - tagViewIdsByKeyword.size;
    tagViewIdsByKeyword.set(normalized, id);
    tagViewKeywordsById.set(id, normalized);
    return id;
  }

  function tagViewKeyword(folderId: number | string | null | undefined): string | null {
    return tagViewKeywordsById.get(Number(folderId)) ?? null;
  }

  function tagViewFolder(folderId: number): FolderRow | null {
    const keyword = tagViewKeyword(folderId);
    if (keyword == null) return null;
    const name = keyword === STARRED_KEYWORD
      ? 'Starred'
      : resolveTag(keyword, settingsStore.get('messageTags')).name;
    return {
      id: folderId,
      name,
      role: null,
      parent_id: null,
      is_starred: 0,
      total_emails: tagCounts.value.get(keyword) ?? 0,
      unread_emails: 0,
    };
  }

  /** A tag view lists the whole mailbox: there is no partial index to report. */
  const tagViewCoverage = computed<number | null>(() => null);
  const tagViewTruncation = computed<{ shown: number; total: number } | null>(() => null);
  /** Accounts shared with the user (RFC 9670); the generated mailbox has none. */
  const sharedAccounts: SharedAccount[] = [];
  const sharedFolderGroups: Array<{ account: SharedAccount; folders: FolderRow[] }> = [];

  function folderById(folderId: number | null | undefined): FolderRow | null {
    if (folderId == null) return null;
    const id = Number(folderId);
    if (isTagViewId(id)) return tagViewFolder(id);
    return folders.value.find((folder) => folder.id === id) ?? null;
  }

  const currentFolder = computed(() => folderById(currentFolderId.value));

  function sortPropFor(folder: { role?: MailboxRole | null } | null | undefined): JmapViewSort {
    if (folder?.role === 'scheduled') return 'scheduled';
    return folder?.role === 'sent' || folder?.role === 'drafts' ? 'sent' : 'received';
  }

  /** Which timestamp a folder's rows show: sent for Sent, Drafts and Scheduled. */
  function sortForFolder(folderId: number | null | undefined): JmapViewSort {
    return sortPropFor(folderById(folderId));
  }
  const currentSort = computed(() => sortPropFor(currentFolder.value));

  // ----- folder views ------------------------------------------------------

  let viewCache: {
    messages: ReadonlyMap<number, Message> | null;
    folderIds: ReadonlyMap<number, number[]> | null;
    views: Map<number, FolderView>;
  } = { messages: null, folderIds: null, views: new Map() };

  function buildRows(folderId: number): Message[] {
    const all = messages.value;
    if (isTagViewId(folderId)) {
      const keyword = tagViewKeyword(folderId);
      if (keyword == null) return [];
      const rows: Message[] = [];
      for (const message of all.values()) {
        if (TAG_VIEW_EXCLUDED.has(message.folder_id)) continue;
        if (messageHasKeyword(message, keyword)) rows.push(message);
      }
      rows.sort((a, b) => (b.received_at - a.received_at) || (b.id - a.id));
      return rows;
    }
    return (folderIds.value.get(folderId) ?? []).map((id) => all.get(id)!);
  }

  const EMPTY_VIEW: FolderView = Object.freeze({
    snapshot: Object.freeze({ messages: Object.freeze([]) as readonly CachedRow[], total: 0 }),
    messages: Object.freeze([]) as readonly CachedRow[],
    total: 0,
    isLoading: false,
  });

  /**
   * The rows a column binds to, newest first. Memoized per mailbox
   * snapshot; reading it tracks the snapshot, so a mutation re-derives it.
   */
  function folderView(folderId: number | null | undefined): FolderView {
    if (folderId == null) return EMPTY_VIEW;
    const id = Number(folderId);
    if (viewCache.messages !== messages.value || viewCache.folderIds !== folderIds.value) {
      viewCache = { messages: messages.value, folderIds: folderIds.value, views: new Map() };
    }
    const cached = viewCache.views.get(id);
    if (cached) return cached;
    const rows = Object.freeze(buildRows(id)) as readonly CachedRow[];
    const snapshot = Object.freeze({ messages: rows, total: rows.length });
    const view: FolderView = markRaw({
      snapshot, messages: rows, total: rows.length, isLoading: false,
    });
    viewCache.views.set(id, view);
    return view;
  }

  function rowsForFolder(folderId: number | null | undefined): readonly CachedRow[] {
    return folderView(folderId).messages;
  }

  // ----- the open message, the cursor and the checked rows ----------------

  const openMessageRef = ref<Attributed>({ id: null, folderId: null });
  const focusedRef = ref<Attributed>({ id: null, folderId: null });
  const selection = ref<{ folderId: number | null; ids: Set<number> }>({ folderId: null, ids: new Set() });

  const selectedMessageId = computed(() => openMessageRef.value.id);
  const selectedMessageFolderId = computed(() => openMessageRef.value.folderId);
  const focusedMessageId = computed(() => focusedRef.value.id);
  const focusedFolderId = computed(() => focusedRef.value.folderId);
  const selectedIds = computed(() => selection.value.ids);
  const selectionFolderId = computed(() => (selection.value.ids.size > 0 ? selection.value.folderId : null));

  function setFocusedMessage(id: number | null, folderId: number | null) {
    focusedRef.value = { id, folderId: id == null ? null : folderId };
  }

  /** Replace the selection with `ids` from `folderId`; an empty set clears it. */
  function setSelection(folderId: number | null, ids: Set<number>) {
    selection.value = { folderId: ids.size > 0 ? folderId : null, ids };
  }

  function clearSelection() {
    if (selection.value.ids.size === 0) return;
    selection.value = { folderId: null, ids: new Set() };
  }

  function findLoadedRow(id: number, _folderId?: number | null): CachedRow {
    return messages.value.get(Number(id));
  }

  const openMessage = computed<CachedRow>(() => (
    openMessageRef.value.id == null ? undefined : messages.value.get(openMessageRef.value.id)
  ));
  /** Folder the open message was opened from; the primary folder when unknown. */
  const openMessageFolderId = computed(() => openMessageRef.value.folderId ?? currentFolderId.value);
  const openMessageFolder = computed(() => folderById(openMessageFolderId.value));

  /** The open message's body, generated on first open and memoized by the generator. */
  const messageBody = computed<MessageBody | null>(() => (
    openMessage.value ? bodyFor(openMessage.value) : null
  ));
  const selectedMessageAddresses = computed<MessageAddress[]>(() => (
    openMessage.value ? messageAddresses(openMessage.value) : []
  ));

  /** Drop the open message, cursor and selection when they belong to `folderId`. */
  function clearInteractionForFolder(folderId: number | null) {
    const matches = (owner: number | null) => (folderId == null ? owner == null : owner === folderId);
    if (openMessageRef.value.id != null && matches(openMessageRef.value.folderId)) {
      openMessageRef.value = { id: null, folderId: null };
    }
    if (matches(focusedRef.value.folderId)) focusedRef.value = { id: null, folderId: null };
    if (selection.value.ids.size > 0 && matches(selection.value.folderId)) {
      selection.value = { folderId: null, ids: new Set() };
    }
  }

  /**
   * Switch the list's folder. The selection, cursor and open message are
   * dropped when they belong to the folder being left or the one being
   * picked (a re-pick resets the list too).
   */
  function selectFolder(folderId: number | null) {
    const previous = currentFolderId.value;
    currentFolderId.value = folderId;
    folderPickCount.value += 1;
    clearInteractionForFolder(previous);
    clearInteractionForFolder(folderId);
  }

  /** Open a message from `folderId` (the list's folder when omitted); opening marks it read. */
  function selectMessage(messageId: number | null, folderId?: number | null) {
    const owner = messageId == null ? null : (folderId ?? currentFolderId.value);
    openMessageRef.value = { id: messageId, folderId: owner };
    setFocusedMessage(messageId, owner);
    if (messageId == null) return;
    const message = messages.value.get(messageId);
    if (message && message.is_seen === 0) {
      messages.value = updateMessages(messages.value, [messageId], (m) => ({ ...m, is_seen: 1 }));
    }
  }

  // ----- flags and tags ----------------------------------------------------

  /** Scheduled sends are read-only outgoing mail: flag and tag changes skip them. */
  function mutableIds(ids: readonly number[]): number[] {
    return ids.filter((id) => {
      const message = messages.value.get(id);
      return message != null && !isScheduledMessage(message);
    });
  }

  async function markManySeen(ids: number[], seen: boolean, _options: BulkSourceOptions = {}): Promise<number> {
    const value = seen ? 1 : 0;
    messages.value = updateMessages(messages.value, ids, (m) => (m.is_seen === value ? m : { ...m, is_seen: value }));
    return ids.length;
  }

  async function toggleManySeen(ids: number[], options: BulkSourceOptions = {}): Promise<number> {
    const anyUnread = ids.some((id) => messages.value.get(id)?.is_seen === 0);
    return markManySeen(ids, anyUnread, options);
  }

  async function markManyFlagged(ids: number[], flagged: boolean, _options: BulkSourceOptions = {}): Promise<number> {
    const value = flagged ? 1 : 0;
    const targets = mutableIds(ids);
    messages.value = updateMessages(messages.value, targets, (m) => (m.is_flagged === value ? m : { ...m, is_flagged: value }));
    return targets.length;
  }

  async function toggleManyFlagged(ids: number[], options: BulkSourceOptions = {}): Promise<number> {
    const anyStarred = mutableIds(ids).some((id) => messages.value.get(id)?.is_flagged === 1);
    return markManyFlagged(ids, !anyStarred, options);
  }

  async function setTagsMany(
    ids: number[],
    { add = [], remove = [] }: { add?: string[]; remove?: string[] },
    _options: BulkSourceOptions = {},
  ): Promise<number> {
    const targets = mutableIds(ids);
    messages.value = updateMessages(messages.value, targets, (m) => withKeywords(m, (keywords) => {
      for (const keyword of remove) {
        for (const key of Object.keys(keywords)) {
          if (normalizeKeyword(key) === normalizeKeyword(keyword)) delete keywords[key];
        }
      }
      for (const keyword of add) keywords[normalizeKeyword(keyword)] = true;
    }));
    return targets.length;
  }

  /** Add `keyword` to every target, or remove it when every target has it. */
  async function toggleTagMany(ids: number[], keyword: string, options: BulkSourceOptions = {}): Promise<number> {
    const normalized = normalizeKeyword(keyword);
    const targets = mutableIds(ids);
    const all = targets.length > 0 && targets.every((id) => messageHasKeyword(messages.value.get(id)!, normalized));
    return setTagsMany(targets, all ? { remove: [normalized] } : { add: [normalized] }, options);
  }

  async function clearTagsMany(ids: number[], _options: BulkSourceOptions = {}): Promise<number> {
    const targets = mutableIds(ids);
    messages.value = updateMessages(messages.value, targets, (m) => withKeywords(m, (keywords) => {
      for (const key of Object.keys(keywords)) {
        if (isTagKeyword(key)) delete keywords[key];
      }
    }));
    return targets.length;
  }

  // ----- moves and deletes ---------------------------------------------------

  /**
   * The row to preview once `ids` leave the folder the open message or the
   * checkbox selection came from: the neighbour after the first removed
   * row, else the one before. Undefined when neither was affected.
   */
  function nextPreviewAfterRemoval(ids: Set<number>): { id: number | null; folderId: number | null } | undefined {
    const open = openMessageRef.value;
    const openRemoved = open.id != null && ids.has(open.id);
    let selectionRemoved = false;
    if (open.id == null && selection.value.ids.size > 0) {
      for (const id of selection.value.ids) {
        if (ids.has(id)) {
          selectionRemoved = true;
          break;
        }
      }
    }
    if (!openRemoved && !selectionRemoved) return undefined;
    const folderId = (openRemoved ? open.folderId : selection.value.folderId) ?? currentFolderId.value;
    const rows = rowsForFolder(folderId);
    const first = rows.findIndex((row) => row != null && ids.has(row.id));
    if (first < 0) return { id: null, folderId };
    for (let i = first + 1; i < rows.length; i += 1) {
      if (!ids.has(rows[i]!.id)) return { id: rows[i]!.id, folderId };
    }
    for (let i = first - 1; i >= 0; i -= 1) {
      if (!ids.has(rows[i]!.id)) return { id: rows[i]!.id, folderId };
    }
    return { id: null, folderId };
  }

  /** Forget the open message, cursor and checked rows among `ids`. */
  function pruneInteraction(ids: Set<number>) {
    if (openMessageRef.value.id != null && ids.has(openMessageRef.value.id)) {
      openMessageRef.value = { id: null, folderId: null };
    }
    if (focusedRef.value.id != null && ids.has(focusedRef.value.id)) {
      focusedRef.value = { id: null, folderId: null };
    }
    if (selection.value.ids.size > 0) {
      const next = new Set(selection.value.ids);
      let changed = false;
      for (const id of ids) if (next.delete(id)) changed = true;
      if (changed) setSelection(selection.value.folderId, next);
    }
  }

  /**
   * Move `ids` to `targetFolderId` (null destroys them), then open the
   * neighbour of the removed rows as Stormbox does.
   */
  function relocate(ids: readonly number[], targetFolderId: number | null) {
    const idSet = new Set(ids.filter((id) => messages.value.has(id)));
    if (idSet.size === 0) return;
    const next = nextPreviewAfterRemoval(idSet);
    const nextMessages = new Map(messages.value);
    const nextFolderIds = new Map(folderIds.value);
    const sources = new Set<number>();
    for (const id of idSet) {
      const message = nextMessages.get(id)!;
      sources.add(message.folder_id);
      if (targetFolderId == null) nextMessages.delete(id);
      else nextMessages.set(id, { ...message, folder_id: targetFolderId });
    }
    for (const folderId of sources) {
      nextFolderIds.set(folderId, nextFolderIds.get(folderId)!.filter((id) => !idSet.has(id)));
    }
    if (targetFolderId != null) {
      const target = [...nextFolderIds.get(targetFolderId)!.filter((id) => !idSet.has(id)), ...idSet];
      target.sort(sortNewestFirst(nextMessages));
      nextFolderIds.set(targetFolderId, target);
    }
    messages.value = nextMessages;
    folderIds.value = nextFolderIds;
    pruneInteraction(idSet);
    if (next !== undefined) selectMessage(next.id, next.id == null ? undefined : next.folderId);
  }

  /** Whether rows from `sourceFolderId` can be dropped on `targetFolderId`. */
  function transferModeForFolder(targetFolderId: number | null | undefined, sourceFolderId?: number | null): 'move' | null {
    if (targetFolderId == null || isTagViewId(targetFolderId)) return null;
    if (sourceFolderId != null && Number(sourceFolderId) === Number(targetFolderId)) return null;
    return folderById(targetFolderId) ? 'move' : null;
  }

  async function moveMessages(ids: number[], targetFolderId: number, _options: BulkSourceOptions = {}) {
    relocate(ids.filter((id) => messages.value.get(id)?.folder_id !== targetFolderId), targetFolderId);
  }

  async function archiveMessages(ids: number[], options: BulkSourceOptions = {}) {
    await moveMessages(ids, ARCHIVE_FOLDER_ID, options);
  }

  async function junkMessages(ids: number[], options: BulkSourceOptions = {}) {
    await moveMessages(ids, JUNK_FOLDER_ID, options);
  }

  /** Not junk: Stormbox whitelists the senders too; here the messages return to the Inbox. */
  async function whitelistSenders(ids: number[], options: BulkSourceOptions = {}) {
    await moveMessages(ids, INBOX_FOLDER_ID, options);
  }

  async function whitelistSender(id: number, options: BulkSourceOptions = {}) {
    await whitelistSenders([id], options);
  }

  /** Delete moves to Trash; deleting from Trash removes the messages for good. */
  async function destroyMessages(ids: number[], _options: BulkSourceOptions = {}) {
    const inTrash = ids.filter((id) => messages.value.get(id)?.folder_id === TRASH_FOLDER_ID);
    const elsewhere = ids.filter((id) => messages.value.has(id) && messages.value.get(id)!.folder_id !== TRASH_FOLDER_ID);
    if (elsewhere.length > 0) relocate(elsewhere, TRASH_FOLDER_ID);
    if (inTrash.length > 0) relocate(inTrash, null);
  }

  async function destroyMessage(id: number, options: BulkSourceOptions = {}) {
    await destroyMessages([id], options);
  }

  async function permanentlyDestroyMessages(ids: number[], _options: BulkSourceOptions = {}) {
    relocate(ids, null);
  }

  /** Cancel a pending scheduled send: the message returns to Drafts. */
  async function cancelScheduledSends(ids: number[]): Promise<boolean> {
    const targets = ids.filter((id) => isScheduledMessage(messages.value.get(id)));
    if (targets.length === 0) return false;
    if (openMessageRef.value.id != null && targets.includes(openMessageRef.value.id)) selectMessage(null);
    messages.value = updateMessages(messages.value, targets, (m) => ({ ...m, scheduled_undo_status: null, is_draft: 1 }));
    await moveMessages(targets, DRAFTS_FOLDER_ID);
    setNotice(targets.length === 1
      ? 'Sending was canceled; the message is back in Drafts.'
      : `Sending was canceled; ${targets.length} messages are back in Drafts.`);
    return true;
  }

  async function cancelScheduledSend(id: number): Promise<boolean> {
    return cancelScheduledSends([id]);
  }

  /** Check every row of a folder view, optionally only the unread or starred ones. */
  async function selectAllLoadedMessages({
    unreadOnly = false,
    flaggedOnly = false,
    folderId = currentFolderId.value,
  }: { unreadOnly?: boolean; flaggedOnly?: boolean; folderId?: number | null } = {}): Promise<number> {
    const next = new Set<number>();
    for (const row of rowsForFolder(folderId)) {
      if (!row) continue;
      if (unreadOnly && row.is_seen !== 0) continue;
      if (flaggedOnly && row.is_flagged !== 1) continue;
      next.add(row.id);
    }
    if (next.size === 0) return 0;
    setSelection(folderId, next);
    return next.size;
  }

  // ----- composed mail -------------------------------------------------------

  /** File a composed message (sent, scheduled or a draft); returns its id. */
  function addMessage(input: Omit<Message, 'id'>): number {
    let id = 0;
    for (const key of messages.value.keys()) if (key > id) id = key;
    id += 1;
    const message: Message = { ...input, id };
    const nextMessages = new Map(messages.value);
    nextMessages.set(id, message);
    const nextFolderIds = new Map(folderIds.value);
    const target = [id, ...nextFolderIds.get(message.folder_id)!];
    target.sort(sortNewestFirst(nextMessages));
    nextFolderIds.set(message.folder_id, target);
    messages.value = nextMessages;
    folderIds.value = nextFolderIds;
    return id;
  }

  function removeMessage(id: number) {
    relocate([id], null);
  }

  // ----- scroll memory -------------------------------------------------------

  const scrollTops = new Map<number, number>();

  function setScrollTop(folderId: number, scrollTop: number) {
    scrollTops.set(folderId, scrollTop);
  }

  function getScrollTop(folderId: number): number {
    return scrollTops.get(folderId) ?? 0;
  }

  // ----- notices -------------------------------------------------------------

  const error = ref<string | null>(null);
  /** Transient confirmation (e.g. a canceled send), rendered by StoreErrorToast. */
  const notice = ref<string | null>(null);
  let noticeTimer: ReturnType<typeof setTimeout> | null = null;
  function setNotice(message: string) {
    notice.value = message;
    if (noticeTimer) clearTimeout(noticeTimer);
    noticeTimer = setTimeout(() => {
      notice.value = null;
      noticeTimer = null;
    }, 5000);
  }

  return {
    contacts,
    folders,
    primaryFolders,
    sidebarPrimaryFolders,
    sharedAccounts,
    sharedFolderGroups,
    tagCounts,
    currentFolderId,
    currentFolder,
    currentSort,
    folderPickCount,
    selectedMessageId,
    selectedMessageFolderId,
    focusedMessageId,
    focusedFolderId,
    selectedIds,
    selectionFolderId,
    openMessage,
    openMessageFolderId,
    openMessageFolder,
    messageBody,
    selectedMessageAddresses,
    tagViewCoverage,
    tagViewTruncation,
    error,
    notice,
    isTagViewId,
    tagViewIdFor,
    tagViewKeyword,
    folderById,
    sortForFolder,
    folderView,
    findLoadedRow,
    setFocusedMessage,
    setSelection,
    clearSelection,
    selectFolder,
    selectMessage,
    markManySeen,
    toggleManySeen,
    markManyFlagged,
    toggleManyFlagged,
    setTagsMany,
    toggleTagMany,
    clearTagsMany,
    transferModeForFolder,
    moveMessages,
    archiveMessages,
    junkMessages,
    whitelistSenders,
    whitelistSender,
    destroyMessages,
    destroyMessage,
    permanentlyDestroyMessages,
    cancelScheduledSend,
    cancelScheduledSends,
    selectAllLoadedMessages,
    addMessage,
    removeMessage,
    setScrollTop,
    getScrollTop,
    setNotice,
  };
});
