import { createApp } from 'vue';
import { createPinia } from 'pinia';

import App from './App.vue';
import { ANIMATIONS_OFF } from './motion';
// The services-ui tokens and button rules first; our own styles win
// collisions because they live on :root (higher specificity than
// services-ui's html).
import './styles/services-ui.css';
import './assets/styles.css';
import './styles/local.css';

if (ANIMATIONS_OFF) document.documentElement.classList.add('no-motion');

const app = createApp(App);
app.use(createPinia());
app.mount('#app');
