<script setup lang="ts">
/**
 * The app shell, from Stormbox's App.vue. Stormbox also gates the shell
 * behind sign-in, runs onboarding, the feature tour and beacons, and
 * hosts the Contacts space, the settings dialog and the tag manager;
 * none of those are part of this build. Contacts shows a placeholder.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
} from 'vue';
import { Bug, Lightbulb, Moon, Plus, Sun, X } from '@lucide/vue';
import AppButton from './components/AppButton.vue';
import mailGlyph from './assets/icons/tb-mail-glyph.svg?raw';

import { useColumnResize } from './composables/useColumnResize';
import { useThunderbirdShortcuts } from './composables/useThunderbirdShortcuts';
import { BUG_REPORT_URL, FEEDBACK_URL } from './defines';
import { ANIMATIONS_OFF } from './motion';

import { useAuthStore } from './stores/auth-store';
import { useMailStore } from './stores/mail-store';
import {
  MESSAGE_COLUMN_MIN_WIDTH,
  MESSAGE_COLUMN_RESIZER_WIDTH,
  useMessageColumnsStore,
} from './stores/message-columns-store';
import { useComposeStore } from './stores/compose-store';
import { useSettingsStore } from './stores/settings-store';
import type { Palette, Theme } from './constants/settings';
import { shortcutAria, shortcutHint } from './constants/shortcuts';

import AppSpaces from './components/AppSpaces.vue';
import FolderTree from './components/FolderTree.vue';
import MessageColumns from './components/MessageColumns.vue';
import MessageView from './components/MessageView.vue';
import ComposeManager from './components/ComposeManager.vue';
import StorageUsageBar from './components/StorageUsageBar.vue';
import StoreErrorToast from './components/StoreErrorToast.vue';
import AppDrawer from './components/AppDrawer.vue';
import AccountAvatarMenu from './components/AccountAvatarMenu.vue';

const authStore = useAuthStore();
const mailStore = useMailStore();
const columnsStore = useMessageColumnsStore();
const composeStore = useComposeStore();
const settingsStore = useSettingsStore();

type AppSpace = 'contacts' | 'mail';

const space = ref<AppSpace>('mail');
const sidebarLabel = computed(() =>
  space.value === 'contacts' ? 'address book list' : 'folder list');
const quickFilterQuery = ref('');
const quickFilterPlaceholder = computed(() =>
  space.value === 'contacts' ? 'Filter contacts or identities' : 'Filter messages',
);
const quickFilterAriaLabel = computed(() =>
  space.value === 'contacts'
    ? 'Filter contacts or identities by name or email address'
    : 'Quick Filter messages by from, to, or subject',
);
const shortcutScheme = computed(() => settingsStore.get('shortcutScheme'));
// The badge shows the scheme's first key; aria lists every binding.
const quickFilterShortcutLabel = computed(() =>
  shortcutHint('quickFilter', shortcutScheme.value)?.split(' or ')[0] ?? '');
const quickFilterAriaShortcut = computed(() =>
  shortcutAria('quickFilter', shortcutScheme.value) ?? undefined);

const inboxUnread = computed(() => {
  const inbox = mailStore.folders.find((folder) => folder.role === 'inbox');
  return Number(inbox?.unread_emails) || 0;
});

const accountLabel = computed(() => authStore.username);

type ResizePane = 'folderList';

const SPACE_RAIL_WIDTH = 56;
const RESIZER_WIDTH = 6;
const COMPACT_READING_WIDTH = 1024;
const SINGLE_COLUMN_WIDTH = 640;
// ?animations=off (motion.ts) shows the reading pane in the same update as
// the folder list hides, instead of after its slide.
const FOLDER_LIST_TRANSITION_MS = ANIMATIONS_OFF ? 0 : 360;
const MESSAGE_VIEW_PRELOAD_MS = 50;
const DEFAULT_COLUMN_WIDTHS = {
  folderList: 240,
};
const MIN_COLUMN_WIDTHS = {
  folderList: 180,
  messageList: MESSAGE_COLUMN_MIN_WIDTH,
  messageView: 240,
};
const MAX_COLUMN_WIDTHS = {
  folderList: 420,
};
const shellEl = ref<HTMLElement | null>(null);
const quickFilterInputEl = ref<HTMLInputElement | null>(null);
const theme = computed<Theme>(() => settingsStore.get('theme'));
const appliedTheme = ref<'dark' | 'light'>(resolveTheme(theme.value));
applyTheme(theme.value);
watch(theme, (value) => applyTheme(value));
const palette = computed<Palette>(() => settingsStore.get('palette'));
applyPalette(palette.value);
watch(palette, (value) => applyPalette(value));
const themeToggleLabel = computed(() =>
  appliedTheme.value === 'dark' ? 'Switch to light mode' : 'Switch to dark mode');
const folderListWidth = ref(DEFAULT_COLUMN_WIDTHS.folderList);
const folderListHidden = ref(false);
// With 'system' the OS decides, so a manual light/dark button would fight it.
const showThemeToggle = computed(() => theme.value !== 'system');
const messageViewMaximized = ref(false);
// A maximized message owns the keyboard unless the composer is open over it.
const shortcutsEnabled = computed(() =>
  !messageViewMaximized.value || composeStore.isExpanded,
);
const windowWidth = ref(typeof window === 'undefined' ? COMPACT_READING_WIDTH : window.innerWidth);
const wantsMessageDetailView = computed(() => mailStore.selectedMessageId != null);
// Multi-select never opens the message view: the bulk actions live in
// the message list header, so a checkbox selection hides the reading
// pane entirely (and works the same in single-column layouts).
const showMessageView = computed(() =>
  wantsMessageDetailView.value && mailStore.selectedIds.size === 0,
);
const displayedMessageView = ref(
  showMessageView.value && !(space.value === 'mail' && windowWidth.value < COMPACT_READING_WIDTH),
);
watch(() => mailStore.selectedMessageId, () => {
  messageViewMaximized.value = false;
});
watch(displayedMessageView, (visible) => {
  if (!visible) messageViewMaximized.value = false;
});
const singleColumnLayout = computed(() => windowWidth.value < SINGLE_COLUMN_WIDTH);
const shouldUseSingleMailColumn = computed(() =>
  space.value === 'mail'
  && showMessageView.value
  && singleColumnLayout.value,
);
const displayedMessageList = computed(() =>
  !(space.value === 'mail' && shouldUseSingleMailColumn.value),
);
let messageViewTimer: number | null = null;
let responsiveFolderListHidden = false;

// Width the columns area asks for: every column plus the handle after
// each one (the last handle exists only beside the reading pane). The
// grid track caps it so the reading pane keeps its minimum; the area
// then scrolls horizontally.
const messageColumnsWidth = computed(() => {
  const columns = columnsStore.columns;
  const resizers = Math.max(0, columns.length - 1) + (displayedMessageView.value ? 1 : 0);
  return columns.reduce((sum, column) => sum + column.width, 0)
    + resizers * MESSAGE_COLUMN_RESIZER_WIDTH;
});

const shellStyle = computed(() => ({
  '--folder-list-width': `${folderListWidth.value}px`,
  '--message-columns-width': `${messageColumnsWidth.value}px`,
  '--message-list-min-width': `${MIN_COLUMN_WIDTHS.messageList}px`,
  '--message-view-min-width': `${MIN_COLUMN_WIDTHS.messageView}px`,
  '--column-resizer-width': `${RESIZER_WIDTH}px`,
  '--folder-list-transition-ms': `${FOLDER_LIST_TRANSITION_MS}ms`,
}));

// No storage key: Stormbox keeps the widths in localStorage, which would
// let one run's layout leak into the next.
const {
  activeResizePane,
  clampPane,
  onResizeHandleKeydown,
  startColumnResize,
} = useColumnResize<ResizePane>({
  panes: {
    folderList: {
      get: () => folderListWidth.value,
      max: () => maxFolderListWidth(),
      min: () => MIN_COLUMN_WIDTHS.folderList,
      set: (width) => {
        folderListWidth.value = width;
      },
      storageKey: 'folderList',
    },
  },
});

useThunderbirdShortcuts({
  space,
  enabled: shortcutsEnabled,
  focusQuickFilter: focusQuickFilterInput,
});

onMounted(() => {
  applyTheme(theme.value);
  applyPalette(palette.value);
  watchSystemTheme();
  applyResponsiveLayout();
  clampColumnWidths();
  window.addEventListener('resize', onWindowResize);
});

onBeforeUnmount(() => {
  clearMessageViewTimer();
  window.removeEventListener('resize', onWindowResize);
  unwatchSystemTheme();
});

watch(showMessageView, () => {
  applyResponsiveLayout();
  clampColumnWidths();
});

watch(space, () => {
  quickFilterQuery.value = '';
  applyResponsiveLayout();
  clampColumnWidths();
});

watch(folderListHidden, () => {
  clampColumnWidths();
});

function startCompose() {
  composeStore.open();
}

function setQuickFilterQuery(event: Event) {
  const next = (event.target as HTMLInputElement | null)?.value ?? '';
  updateQuickFilterQuery(next);
}

function clearQuickFilterQuery() {
  updateQuickFilterQuery('');
}

function focusQuickFilterInput() {
  quickFilterInputEl.value?.focus();
  quickFilterInputEl.value?.select();
}

function updateQuickFilterQuery(next: string) {
  if (next === quickFilterQuery.value) return;
  if (space.value === 'mail' && mailStore.selectedMessageId != null) {
    mailStore.selectMessage(null);
  }
  quickFilterQuery.value = next;
}

function requestSpaceChange(next: string) {
  if (next !== 'mail' && next !== 'contacts') return;
  space.value = next;
}

function toggleFolderList() {
  folderListHidden.value = !folderListHidden.value;
  responsiveFolderListHidden = false;
}

function toggleTheme() {
  const nextTheme = appliedTheme.value === 'dark' ? 'light' : 'dark';
  void settingsStore.update({ theme: nextTheme });
}

function onWindowResize() {
  windowWidth.value = window.innerWidth;
  applyResponsiveLayout();
  clampColumnWidths();
}

// The message view collapses the sidebar in the compact layout (R-10.2).
function detailPaneVisible() {
  return space.value === 'mail' && showMessageView.value;
}

function applyResponsiveLayout() {
  const compactLayout = windowWidth.value < COMPACT_READING_WIDTH;
  const shouldHideFolderList = singleColumnLayout.value || (compactLayout && detailPaneVisible());
  const shouldShowSingleColumn = shouldUseSingleMailColumn.value;
  const willHideFolderList = shouldHideFolderList && !folderListHidden.value;

  if (shouldHideFolderList) {
    if (!folderListHidden.value) {
      responsiveFolderListHidden = true;
    }
    folderListHidden.value = true;
  } else if (responsiveFolderListHidden) {
    folderListHidden.value = false;
    responsiveFolderListHidden = false;
  }

  syncDisplayedMessageView({
    delayForFolderSlide: space.value === 'mail' && willHideFolderList && !shouldShowSingleColumn,
  });
}

function syncDisplayedMessageView({ delayForFolderSlide = false } = {}) {
  clearMessageViewTimer();
  if (!showMessageView.value) {
    displayedMessageView.value = false;
    return;
  }

  if (!delayForFolderSlide || FOLDER_LIST_TRANSITION_MS === 0) {
    displayedMessageView.value = true;
    return;
  }

  displayedMessageView.value = false;
  messageViewTimer = window.setTimeout(() => {
    messageViewTimer = null;
    if (showMessageView.value) {
      displayedMessageView.value = true;
    }
  }, Math.max(0, FOLDER_LIST_TRANSITION_MS - MESSAGE_VIEW_PRELOAD_MS));
}

function clearMessageViewTimer() {
  if (messageViewTimer == null) return;
  window.clearTimeout(messageViewTimer);
  messageViewTimer = null;
}

function availablePaneWidth() {
  const shellWidth = shellEl.value?.clientWidth || window.innerWidth || 0;
  const resizerCount = folderListHidden.value ? 0 : 1;
  return Math.max(0, shellWidth - SPACE_RAIL_WIDTH - resizerCount * RESIZER_WIDTH);
}

// Width the panes beside the sidebar need so it can never push them into
// horizontal overflow (R-10.1): every open message list column at its
// minimum (with the handles between them) plus the message view minimum.
function sidebarNeighbourReserve() {
  const columnCount = Math.max(1, columnsStore.columns.length);
  const columnsMinimum = columnCount * MESSAGE_COLUMN_MIN_WIDTH
    + (columnCount - 1) * MESSAGE_COLUMN_RESIZER_WIDTH;
  return displayedMessageView.value
    ? columnsMinimum + MESSAGE_COLUMN_RESIZER_WIDTH + MIN_COLUMN_WIDTHS.messageView
    : columnsMinimum;
}

function maxFolderListWidth() {
  return Math.min(
    MAX_COLUMN_WIDTHS.folderList,
    availablePaneWidth() - sidebarNeighbourReserve(),
  );
}

function clampColumnWidths() {
  if (!folderListHidden.value) {
    clampPane('folderList');
  }
}

function resolveTheme(value: Theme): 'dark' | 'light' {
  if (value !== 'system') return value;
  if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
  }
  return 'dark';
}

function applyTheme(value: Theme) {
  if (typeof document === 'undefined') return;
  const resolved = resolveTheme(value);
  appliedTheme.value = resolved;
  // services-ui drives theming off a `dark` class on <html>; we add an
  // explicit `light` class too so an explicit light choice can override
  // a dark system preference. Our own tokens key off the same classes.
  const root = document.documentElement;
  root.classList.toggle('dark', resolved === 'dark');
  root.classList.toggle('light', resolved === 'light');
  root.style.colorScheme = resolved;
}

// The stylesheets default to the classic palette; `palette-bolt` on <html>
// activates every Bolt override in assets/bolt-theme.css (not part of
// this build, which always uses the classic palette).
function applyPalette(value: Palette) {
  if (typeof document === 'undefined') return;
  document.documentElement.classList.toggle('palette-bolt', value === 'bolt');
}

let systemThemeMedia: MediaQueryList | null = null;

function onSystemThemeChange() {
  if (theme.value === 'system') applyTheme('system');
}

function watchSystemTheme() {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return;
  systemThemeMedia = window.matchMedia('(prefers-color-scheme: light)');
  systemThemeMedia.addEventListener?.('change', onSystemThemeChange);
}

function unwatchSystemTheme() {
  systemThemeMedia?.removeEventListener?.('change', onSystemThemeChange);
  systemThemeMedia = null;
}
</script>

<template>
  <div
    ref="shellEl"
    class="shell"
    :class="{
      'shell--message-view-hidden': space === 'mail' && !displayedMessageView,
      'shell--message-list-hidden': space === 'mail' && !displayedMessageList,
      'shell--message-view-maximized': messageViewMaximized,
      'shell--folder-list-hidden': folderListHidden,
      'shell--contacts': space === 'contacts',
      'shell--column-resizing': activeResizePane !== null,
    }"
    :style="shellStyle"
  >
    <header class="quick-filter" :inert="messageViewMaximized" :aria-hidden="messageViewMaximized">
      <div class="quick-filter__brand">
        <span class="quick-filter__glyph" aria-hidden="true" v-html="mailGlyph" />
        <span class="quick-filter__wordmark">Mail</span>
      </div>

      <div class="quick-filter__search" role="search">
        <input
          ref="quickFilterInputEl"
          class="quick-filter__input"
          :class="{ 'quick-filter__input--empty': quickFilterQuery.length === 0 }"
          type="search"
          :value="quickFilterQuery"
          :aria-label="quickFilterAriaLabel"
          :aria-keyshortcuts="quickFilterAriaShortcut"
          :placeholder="quickFilterPlaceholder"
          autocomplete="off"
          spellcheck="false"
          @input="setQuickFilterQuery"
        />
        <kbd
          v-if="quickFilterQuery.length === 0"
          class="quick-filter__shortcut"
          aria-hidden="true"
        >{{ quickFilterShortcutLabel }}</kbd>
        <button
          v-if="quickFilterQuery.length > 0"
          class="quick-filter__clear"
          type="button"
          aria-label="Clear Quick Filter"
          title="Clear Quick Filter"
          @click="clearQuickFilterQuery"
        >
          <X :size="17" :stroke-width="2.25" aria-hidden="true" />
        </button>
      </div>

      <div class="quick-filter__actions">
        <a
          class="quick-filter__action"
          :href="BUG_REPORT_URL"
          aria-label="Report a bug"
          title="Report a bug"
        >
          <Bug :size="18" :stroke-width="1.75" aria-hidden="true" />
        </a>
        <a
          class="quick-filter__action"
          :href="FEEDBACK_URL"
          aria-label="Give feedback"
          title="Give feedback"
        >
          <Lightbulb :size="18" :stroke-width="1.75" aria-hidden="true" />
        </a>
        <button
          v-if="showThemeToggle"
          class="quick-filter__action theme-toggle"
          type="button"
          :aria-label="themeToggleLabel"
          :title="themeToggleLabel"
          @click="toggleTheme"
        >
          <Sun v-if="appliedTheme === 'dark'" :size="18" :stroke-width="1.75" aria-hidden="true" />
          <Moon v-else :size="18" :stroke-width="1.75" aria-hidden="true" />
        </button>
        <AppDrawer />
        <AccountAvatarMenu />
      </div>
    </header>

    <AppSpaces
      :inert="messageViewMaximized"
      :aria-hidden="messageViewMaximized"
      :active="space"
      :unread-count="inboxUnread"
      :folder-list-hidden="folderListHidden"
      :sidebar-label="sidebarLabel"
      @change="requestSpaceChange"
      @toggle-folder-list="toggleFolderList"
    />

    <div
      class="sidebar-slot"
      :class="{ 'sidebar-slot--hidden': folderListHidden }"
      :aria-hidden="folderListHidden || messageViewMaximized"
      :inert="folderListHidden || messageViewMaximized"
    >
      <aside v-if="space === 'mail'" class="sidebar">
        <header class="sidebar__header">
          <AppButton class="sidebar__compose" @click="startCompose">
            <template #iconLeft>
              <Plus :size="16" :stroke-width="2" />
            </template>
            New Message
          </AppButton>
        </header>

        <div class="sidebar__account">
          <span class="sidebar__account-name">{{ accountLabel }}</span>
        </div>

        <FolderTree />

        <footer class="sidebar__footer">
          <StorageUsageBar />
        </footer>
      </aside>
      <div
        v-else
        class="sidebar sidebar--contacts"
      />
    </div>

    <div
      class="column-resizer column-resizer--folder-list"
      :class="{
        'is-active': activeResizePane === 'folderList',
        'column-resizer--hidden': folderListHidden,
      }"
      role="separator"
      :aria-label="`Resize ${sidebarLabel}`"
      aria-orientation="vertical"
      :aria-valuemin="MIN_COLUMN_WIDTHS.folderList"
      :aria-valuemax="maxFolderListWidth()"
      :aria-valuenow="folderListWidth"
      :aria-hidden="folderListHidden || messageViewMaximized"
      :inert="messageViewMaximized"
      :tabindex="folderListHidden || messageViewMaximized ? -1 : 0"
      @pointerdown="startColumnResize('folderList', $event)"
      @keydown="onResizeHandleKeydown('folderList', $event)"
    />

    <template v-if="space === 'mail'">
      <MessageColumns
        v-if="displayedMessageList"
        :inert="messageViewMaximized"
        :aria-hidden="messageViewMaximized"
        :quick-filter-query="quickFilterQuery"
        :reading-pane-visible="displayedMessageView"
      />
      <MessageView
        v-if="displayedMessageView"
        :maximized="messageViewMaximized"
        @toggle-maximized="messageViewMaximized = !messageViewMaximized"
      />
    </template>
    <section v-else class="contacts contacts--placeholder" aria-label="Contacts">
      <p>Contacts are not part of this build.</p>
    </section>

    <ComposeManager />
    <StoreErrorToast />
  </div>
</template>

<style>
:root {
  --surface: var(--panel);
  --fg: var(--text);
  --spaces-bar-height: calc(56px + env(safe-area-inset-bottom));
  --border-soft: color-mix(in srgb, var(--border) 55%, transparent);
  --accent-bg: color-mix(in srgb, var(--accent) 22%, var(--panel2));
  --accent-fg: var(--accent);
  /* Chrome on the Bolt ramp (assets/styles.css). Dark: content on lower,
     folder list, popovers and dialogs on base, rail and top nav on raised.
     Light steps the other way (html.light below). */
  --space-rail-bg: var(--colour-neutral-raised);
  --space-rail-fg: var(--muted);
  --folder-list-bg: var(--colour-neutral-base);
  /* Top nav: same 56px band as before, sharing the rail's surface. The
     Bolt palette (assets/bolt-theme.css) re-points these tokens. */
  --top-nav-height: 56px;
  --top-nav-bg: var(--space-rail-bg);
  /* Modal look shared by every dialog (the Welcome modal defines it): a
     base-surface card with a border edge over a dark blurred scrim. */
  --modal-bg: var(--colour-neutral-base);
  --modal-surface: var(--modal-bg);
  --modal-border: var(--control-border);
  --modal-shadow:
    0 28px 80px color-mix(in srgb, #000 46%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 8%, transparent);
  --modal-scrim: color-mix(in srgb, #000 64%, transparent);
  --modal-scrim-blur: blur(12px);
  --top-nav-wordmark: var(--accent);
  --top-nav-input-bg: var(--surface);
  --top-nav-popover-bg: var(--colour-neutral-base);
}

html.light,
.light {
  /* Content, dialogs and popovers on base, folder list on lower, rail and
     top nav on subtle. */
  --space-rail-bg: var(--colour-neutral-subtle);
  --folder-list-bg: var(--colour-neutral-lower);
  --top-nav-wordmark: var(--accent);
}

/* The columns area asks for the sum of its column widths; the grid gives
   it that much only while the reading pane keeps its minimum, and the
   area scrolls horizontally past that (the column handles live inside
   it, so no resizer track sits between the two). */
.shell {
  position: relative;
  --folder-resizer-width: var(--column-resizer-width, 6px);
  display: grid;
  grid-template-columns:
    56px
    auto
    var(--folder-resizer-width)
    minmax(var(--message-list-min-width, 280px), var(--message-columns-width, 360px))
    minmax(var(--message-view-min-width, 320px), 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  height: var(--app-viewport-height);
  background: var(--panel);
  color: var(--text);
  overflow: hidden;
}
.shell--message-view-hidden {
  grid-template-columns:
    56px
    auto
    var(--folder-resizer-width)
    minmax(var(--message-list-min-width, 280px), 1fr)
    0px;
}
.shell--message-list-hidden {
  grid-template-columns:
    56px
    auto
    var(--folder-resizer-width)
    0px
    minmax(0, 1fr);
}
.shell--folder-list-hidden {
  --folder-resizer-width: 0px;
}
.shell--contacts {
  grid-template-columns:
    56px
    auto
    var(--folder-resizer-width)
    minmax(0, 1fr);
}
/* While a feature spotlight runs, the tour caption sits along the top edge
 * (FeatureCardGrid) and the composer sits directly beneath it. The dialog's
 * own backdrop is dropped so the scrim is the only dimming. The dock lifts
 * off the bottom edge so its ring is not clipped by the viewport. Three
 * classes outrank the components' scoped `[data-v]` rules. */
.shell.shell--spotlighting .compose-dialog {
  --spotlight-caption-space: 112px;
  align-items: start;
  padding-top: var(--spotlight-caption-space);
  box-sizing: border-box;
  background: transparent;
}
.shell.shell--spotlighting .compose-dialog__card {
  height: min(640px, calc(100vh - var(--spotlight-caption-space) - 24px));
}
.shell.shell--spotlighting .compose-dock {
  bottom: 14px;
}
.shell.shell--spotlighting .compose-dock__item {
  border-bottom: 2px solid var(--compose-dock-outline);
  border-radius: 10px;
}
/* The folder manager the tour opens sits above the scrim (120 > 90); its
 * own backdrop would dim the caption, so the scrim is the only dimming. */
body.spotlighting .folder-subs {
  background: transparent;
}
/* Grid items default to min-height: auto, which makes inner
 * overflow:auto containers grow to their content instead of scrolling.
 * Force every shell column to be allowed to shrink so its children can
 * own the vertical scroll. */
.shell > * { min-height: 0; min-width: 0; }
.shell > .msg-columns {
  grid-column: 4;
}
.shell > .message-view {
  grid-column: 5;
}
.shell--message-view-maximized > .message-view {
  position: fixed;
  inset: 0;
  z-index: 45;
  width: 100%;
  height: var(--app-viewport-height);
}
.shell--message-view-maximized > :is(
  .quick-filter,
  .app-spaces,
  .sidebar-slot,
  .column-resizer,
  .msg-columns
) {
  visibility: hidden;
}
.shell--message-list-hidden > .message-view {
  grid-column: 4 / -1;
}
.shell > .contacts { grid-column: 4 / -1; }

.quick-filter {
  grid-column: 1 / -1;
  position: relative;
  display: flex;
  align-items: center;
  column-gap: 16px;
  height: var(--top-nav-height);
  padding: 0 16px 0 14px;
  /* No bottom hairline: the bar reads as one surface with the sidebar. */
  background: var(--top-nav-bg);
}
.quick-filter__brand {
  display: inline-flex;
